\]
\[
BDB^{-1} = \begin{pmatrix}1&4\\0&1\end{pmatrix}
\begin{pmatrix}2&0\\0&3 \end{pmatrix}
\begin{pmatrix}1&-4\\0&1\end{pmatrix} = \begin{pmatrix}2&4\\0&3 \end{pmatrix}
\]

