\item Utiliser que \( e^t-1 = t \cdot \mu(t) \), pour une certaine fonction \( \mu \) qui vérifie \( \mu(t) \to 1 \) lorsque \( t\to 0 \).
\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Comme \( -1 \le \sin \frac 1x \le +1 \) alors \( 1 \le 2 + \sin \frac 1x \le +3 \). Donc pour \( x>0 \), nous obtenons \( \frac x3 \le \frac{x}{2+\sin \frac{1}{x}} \le x \). On obtient une inégalité similaire pour \( x<0 \). Cela implique \( \lim\limits_{x\rightarrow 0}\frac{x}{2+\sin \frac{1}{x}} = 0 \).

\item Sachant que \( \frac{\ln (1+t)}{t} \to 1 \) lorsque \( t \to 0 \), on peut le reformuler ainsi \( \ln(1+t) = t \cdot \mu(t) \), pour une certaine fonction \( \mu \) qui vérifie \( \mu(t) \to 1 \) lorsque \( t\to 0 \). Donc \( \ln (1+e^{-x}) = e^{-x} \mu(e^{-x}) \). Maintenant

\begin{align*}
	(\ln (1+e^{-x}))^{\frac{1}{x}}
	& = \exp \left(\frac{1}{x} \ln\left( \ln (1+e^{-x}) \right) \right)      \\
	& = \exp \left(\frac{1}{x} \ln \left( e^{-x} \mu(e^{-x}) \right) \right) \\
	& = \exp \left(\frac{1}{x} \left( -x + \ln \mu(e^{-x}) \right) \right)   \\
	& = \exp \left( -1 + \frac{\ln \mu(e^{-x})}{x} \right)
\end{align*}
\( \mu(e^{-x}) \to 1 \) donc \( \ln\mu(e^{-x}) \to 0 \), donc \( \frac{\ln \mu(e^{-x})}{x} \to 0 \) lorsque \( x \to +\infty \).

Bilan : la limite est \( \exp(-1) = \frac{1}{e} \).

\item

\item Sachant \( \frac{e^x - 1}{x} \to 1 \) lorsque \( x\to 0 \), on reformule ceci en \( e^x-1 = x \cdot \mu(x) \), pour une certaine fonction \( \mu \) qui vérifie \( \mu(x) \to 1 \) lorsque \( x\to 0 \). Cela donne \( \ln (e^x-1) = \ln (x \cdot \mu(x)) = \ln x + \ln \mu(x) \).
\begin{align*}
	x^{\frac{1}{\ln (e^x-1)}}
	& = \exp\left( \frac{1}{\ln (e^x-1)} \ln x \right)            \\
	& = \exp\left( \frac{1}{\ln x + \ln \mu(x)} \ln x \right)     \\
	& = \exp\left( \frac{1}{1 + \frac{\ln \mu(x)}{\ln x}} \right)
\end{align*}
Maintenant \( \mu(x) \to 1 \) donc \( \ln \mu(x) \to 0 \), et \( \ln x \to - \infty \) lorsque \( x \to 0 \). Donc \( \frac{\ln \mu(x)}{\ln x} \to 0 \). Cela donne
\[
\lim\limits_{x\rightarrow 0^{+}}x^{\frac{1}{\ln (e^x-1)}} = \lim\limits_{x\rightarrow 0^{+}} \exp\left( \frac{1}{1 + \frac{\ln \mu(x)}{\ln x}} \right) = \exp\left(1\right) = e.
\]
\end{enumerate}

Pour \( x>0 \), \( (x^x)^x = e^{x\ln(x^x)} = e^{x^2\ln x} \) et \( x^{(x^x)} = e^{x^x\ln x} \). Par suite,

\[
\forall x>0,\;\frac{(x^x)^x}{x^{(x^x)}} = \text{exp}(\ln x(x^2-x^x)).
\]
Or, \( x^2-x^x = -x^x(1-x^{2-x}) = -e^{x\ln x}(1-e^{(2-x)\ln x}) \). Quand \( x \) tend vers \( +\infty \), \( (2-x)\ln x \) tend vers \( -\infty \). Donc, \( 1-e^{(2-x)\ln x} \) tend vers \( 1 \) puis \( x^2-x^x \) tend vers \( -\infty \). Mais alors, \( \ln x(x^2-x^x) \) tend vers \( -\infty \), puis \( \frac{(x^x)^x}{x^{(x^x)}} = \mbox{exp}(\ln x(x^2-x^x)) \) tend vers \( 0 \).

\begin{center}
\shadowbox{ \( \lim_{x\rightarrow +\infty}\frac{(x^x)^x}{x^{(x^x)}} = 0 \). }
\end{center}

\begin{enumerate}
\item Pour tout \( n \ge 2 \) on a : \( P_n(0) = -1 \) et \( P_n(1) = 3 \). Comme l'application \( X\mapsto P_n(X) \) est continue, elle s'annule en (au moins) un point de l'intervalle \( \rbrack 0, 1 \lbrack \). Comme par ailleurs, pour tout \( X \) positif, \( P'_n(X) = nX^{n-1}+(n-1)X^{n-2}+2X+1 \) est strictement positif, l'application \( X\mapsto P_n(X) \) est strictement croissante sur \( \Rr_+ \) et s'annule en au plus un point de \( \Rr_+ \). En conséquence \( P_n \) a une unique racine positive \( \lambda_n \) qui de plus satisfait l'inégalité \( 0<\lambda_n<1 \).

\item Pour tout \( X\in \rbrack 0, 1 \lbrack , P_n(X)-P_{n-1}(X) = X^n-X^{n-2}<0 \). En particulier \( P_n(\lambda_{n-1})<0 \) donc \( \lambda_n>\lambda_{n-1} \). La suite \( (\lambda_n)_{n\ge 3} \) est donc croissante et majorée (cf 1.) : elle est convergente.

\item Pour tout \( n \ge 3 \) on a : \( \lambda_n^n+\lambda_n^{n-1} = -\lambda_n^2-\lambda_n+1 \). Or \( \displaystyle{ P_n\Bigl( \frac{3}{4}\Bigr) >\Bigl( \frac{3}{4}\Bigr)^2+\frac{3}{4}-1>0} \) donc la suite \( (\lambda_n^n+\lambda_n^{n-1})_{n \ge 3} \) satisfait les inégalités \( 0<\lambda_n^n+\lambda_n^{n-1}<\displaystyle{ \Bigl(
	\frac{3}{4}\Bigr)^n+\Bigl(\frac{3}{4} \Bigr)^{n+1}} \) et converge vers \( 0 \). Il en va de même de la suite \( (-\lambda_n^2-\lambda_n+1)_{n\ge 2} \). En passant à la limite, on obtient l'égalité : \( \ell^2+\ell -1 = 0 \). La seule solution positive de cette équation étant \( \displaystyle{\frac{ -1+\sqrt{5} }{ 2}} \), on a l'égalité : \( \ell = \displaystyle{ \frac{ -1+\sqrt{5}}{ 2}} \).
	\end{enumerate}

	\bigskip
	\noindent \textbf{Remarques}
	\begin{enumerate}
\item L'inégalité \( 0<\lambda_n <1 \) (pour tout \( n\ge 2 \)) n'implique pas que \( (\lambda_n^n )_{n\ge 2} \) converge vers \( 0 \). Par exemple la suite \( (v_n)_{n \ge 1} \) définie par \( v_n = \displaystyle {(1 -\frac{1}{n})^n} \) converge vers \( \displaystyle{\frac{1}{e}} \).

\item La propriété \( \displaystyle{\lim_{n\rightarrow \infty} \frac{1}{n+k}\epsilon \Bigl( \frac{1}{n+k} \Bigr) } = 0 \) n'implique pas que \( \displaystyle{\lim_{n\rightarrow \infty} \sum_{\scriptstyle k = 0}^{\scriptstyle n}\frac{1}{n+k}\epsilon \Bigl( \frac{1}{n+k} \Bigr) } = 0 \). Par exemple... \( \displaystyle{\lim_{n\rightarrow \infty} \sum_{\scriptstyle k = 0}^{\scriptstyle n}\frac{1}{n+k}} = \hbox{log }(2) \).
\end{enumerate}

\begin{enumerate}
\item \( f_\lambda'(x) = \lambda e^x+2x \), \( f_\lambda''(x) = \lambda e^x+2 \). Les points d'inflexion sont les racines de \( f_\lambda'' \), donc si \( \lambda \ge 0 \) il n'y a pas de point d'inflexion, si \( \lambda < 0 \) alors il y a un point d'inflexion en \( x_\lambda = \ln(-2/\lambda) \).

\item Si \( \lambda \ge 0 \) alors \( f_\lambda'' \) est toujours strictement positive, donc \( f_\lambda' \) est strictement croissante, en \( -\infty \) la limite de \( f_\lambda' \) est \( -\infty \), en \( +\infty \) la limite de \( f_\lambda' \) est \( +\infty \), donc il existe un unique réel \( y_\lambda \) tel que \( f'_\lambda(y_\lambda) = 0 \). \( f_\lambda \) est décroissante sur \( ]-\infty,y_\lambda] \) et croissante sur \( [y_\lambda, +\infty[ \). Et en \( y_\lambda \) nous avons un minimum absolu.

\item Nous supposons \( \lambda < 0 \). Alors \( f_\lambda'' \) s'annule seulement en \( x_\lambda \). \( f_\lambda' \) est croissante sur \( ]-\infty,x_\lambda] \) et décroissante sur \( [x_\lambda, +\infty[ \). Donc \( f_\lambda' \) a des racines si et seulement si \( f_\lambda'(x_\lambda) \ge 0 \). Or \( f_\lambda'(x_\lambda) = -2+2x_\lambda \).
\begin{enumerate}
	\item Si \( \lambda = -2/e \) alors \( f_\lambda'(x_\lambda) = 0 \). Comme \( f_\lambda''(x_\lambda) = 0 \) et \( f_\lambda''' \) ne s'annule pas alors \( x_\lambda \) est un point d'inflexion qui n'est pas un extrémum local.

	\item Si \( \lambda>-2/e \) alors \( f_\lambda'(x_\lambda) <0 \) donc \( f_\lambda' \) est négative donc \( f_\lambda \) est strictement décroissante. Il n'y a pas d'extrémum local.

	\item Si \( -2/e<\lambda<0 \) alors \( f_\lambda'(x_\lambda) > 0 \). Donc \( f_\lambda' \) s'annule en deux points, une fois sur \( ]-\infty,x_\lambda[ \) et une fois sur \( ]x_\lambda,+\infty[ \). Ce sont des extrémums locaux (minimum et maximum respectivement).
\end{enumerate}
\end{enumerate}

