		\item Étudier l'existence des limites (dans \( \overline\Rr\ \),) en \( +\infty \) de \( f(x) \), \( f'(x) \), \( \frac{f(x)}x \).

		\item Même question pour les limites en \( -\infty \) de \( f(x) \), \( f'(x) \), et \( xf'(x) \).

	\end{enumerate}

