\[
(x-x^2)\ln(\sin x)\underset{x\rightarrow0}{ = }(x-x^2)\ln x+(x-x^2)\ln\left(1-\frac{x^2}{6}+o(x^2)\right) = x\ln x-x^2\ln x+o(x^2\ln x).
\]
Ensuite,

\[
\sin x\ln(x-x^2)\underset{x\rightarrow0}{ = }\left(x-\frac{x^3}{6}+o(x^3)\right)(\ln x+\ln(1-x)) = (x-\frac{x^3}{6}+o(x^3))(\ln x-x+o(x)) = x\ln x+o(x^2\ln x).
\]
Donc,

\begin{align*}\ensuremath (\sin x)^{x-x^2}-(x-x^2)^{\sin x} & =e^{x\ln x}(e^{-x^2\ln x+o(x^2\ln x)}-e^{o(x^2\ln x)})=e^{x\ln x}(1-x^2\ln x-1+o(x^2\ln x)) \\
