\item \( 50p^3 = 27q^2 \).

\item \( a^2+b^2+c^2 = 2c^2 + 1 = -2p \Rightarrow \) l'une des racines de l'équation aux carrés (\( -Y^3 -2pY^2 -p^2Y + q^2 \)) doit être \( -p - \frac 12 \). CNS \( \Leftrightarrow 2p+1 + 8q^2 = 0 \).
\end{enumerate}

\begin{enumerate}
\item Les coefficients de \( P \) sont bornés.

\item \( \widetilde P(X^2) = (-1)^nP(X)P(-X) \Rightarrow \widetilde P \in {\Zz[X]} \).

\item La suite \( (\widetilde {\dot{\dot{\widetilde P}}}) \) prend un nombre fini de valeurs.
\end{enumerate}

exercices.enonce:
Soit \( P \) un polynôme à coefficients entiers relatifs de degré supérieur ou égal à \( 1 \). Soit \( n \) un entier relatif et \( m = P(n) \).
	\begin{enumerate}
		\item Montrer que \( \forall k\in\Zz,\;P(n+km) \) est un entier divisible par \( m \).

		\item Montrer qu'il n'existe pas de polynômes non constants à coefficients entiers tels que \( P(n) \) soit premier pour tout entier \( n \).
	\end{enumerate}

Soit \( E \) la partie de \( \Cc[X] \) formée des polynômes \( P \) vérifiant \( \forall a\in\Zz,\;P(a)\in\Zz \).
	\begin{enumerate}
		\item On pose \( P_0 = 1 \) et pour \( n \) entier naturel non nul, \( P_n = \frac{1}{n!}\prod_{k = 1}^n(X+k) \) (on peut définir la notation \( P_n = C_{X+n}{n} \)). Montrer que \( \forall n\in\Nn,\;P_n\in E \).

		\item Montrer que toute combinaison linéaire à coefficients entiers relatifs des \( P_n \) est encore un élément de \( E \).

		\item Montrer que \( E \) est l'ensemble des combinaisons linéaires à coefficients entiers relatifs des \( P_n \).
	\end{enumerate}

Résoudre dans \( \Cc^3 \) (resp. \( \Cc^4 \)) le système :

	\[
	1)\;\left\{
	\begin{array}{l}
		x+y+z = 1                               \\
		\frac{1}{x}+\frac{1}{y}+\frac{1}{z} = 1 \\
		xyz = -4
	\end{array}
	\right.
	\quad2)\;\left\{
	\begin{array}{l}
		x+y+z+t = 0          \\
		x^2+y^2+z^2+t^2 = 10 \\
		x^3+y^3+z^3+t^3 = 0  \\
		x^4+y^4+z^4+t^4 = 26
	\end{array}
	\right. .
	\]

exercices.correction:
\begin{enumerate}
\item
\begin{align*}\ensuremath S & \Leftrightarrow\left\{
	\begin{array}{l}
		x+y+z=1                \\
		\frac{xy+xz+yz}{xyz}=1 \\
		xyz=-4
	\end{array}\right.\Leftrightarrow\sigma_1=1,\;\sigma_2=\sigma_3=-4                                      \\
	& \Leftrightarrow x,\;y\;\mbox{et}\;z\;\mbox{sont les trois solutions de l'équation}\;X^3-X^2-4X+4=0    \\
	& \Leftrightarrow x,\;y\;\mbox{et}\;z\;\mbox{sont les trois solutions de l'équation}\;(X-1)(X-2)(X+2)=0 \\
	& \Leftrightarrow(x,y,z)\in\{(1,2,-2),(1,-2,2),(2,1,-2),(2,-2,1),(-2,1,2),(-2,2,1)\}
\end{align*}

\item Pour \( 1\le k\le 4 \), posons \( S_k = x^k+y^k+z^k+t^k \). On a \( S_2 = \sigma_1^2-2\sigma_2 \). Calculons \( S_3 \) en fonction des \( \sigma_k \). On a \( \sigma_1^3 = S_3+3\sum_{}^{}x^2y+6\sum_{}^{}xyz = S_3+3\sum_{}^{}x^2y+6\sigma_3 \) \( (*) \). Mais on a aussi \( S_1S_2 = S_3+\sum_{}^{}x^2y \). Donc, \( \sum_{}^{}x^2y = \sigma_1(\sigma_1^2-2\sigma_2)-S_3 \). En reportant dans \( (*) \), on obtient \( \sigma_1^3 = S_3+3(\sigma_1^3-2\sigma_1\sigma_2-S_3)+6\sigma_3 \) et donc,

\[
S_3 = \frac{1}{2}(-\sigma_1^3+3(\sigma_1^3-2\sigma_1\sigma_2-S_3)+6\sigma_3) = \sigma_1^3-3\sigma_1\sigma_2+3\sigma_3.
\]
Calculons \( S_3 \) en fonction des \( \sigma_k \). Soit \( P = (X-x)(X-y)(X-z)(X-t) = X^4-\sigma_1X^3+\sigma_2X^2-\sigma_3X+\sigma_4 \).

\begin{align*}\ensuremath P(x)+P(y)+P(z)+P(t)=0 & \Leftrightarrow S_4-\sigma_1S_3+\sigma_2S_2-\sigma_3S_1+4\sigma_4=0                                                            \\
	& \Leftrightarrow S_4=\sigma_1(\sigma_1^3-3\sigma_1\sigma_2+3\sigma_3)-\sigma_2(\sigma_1^2-2\sigma_2)+\sigma_3\sigma_1-4\sigma_4 \\
	& \Leftrightarrow S_4=\sigma_1^4-4\sigma_1^2\sigma_2+4\sigma_1\sigma_3+2\sigma_2^2-4\sigma_4.
\end{align*}

Par suite,

\begin{align*}\ensuremath S & \Leftrightarrow
	\left\{
	\begin{array}{l}
		\sigma_1=0    \\
		-2\sigma_2=10 \\
		3\sigma_3=0   \\
		2\sigma_2^2-4\sigma_4=26
	\end{array}
	\right.\Leftrightarrow\left\{
	\begin{array}{l}
		\sigma_1=0  \\
		\sigma_2=-5 \\
		\sigma_3=0  \\
		\sigma_4=6
	\end{array}
	\right.                                                                                                                               \\
	& \Leftrightarrow x,\;y,\;z,\;\mbox{et}\;t\;\mbox{sont les 4 solutions de l'équation}\;X^4-5X^2+6=0                     \\
	& \Leftrightarrow(x,y,z,t)\;\mbox{est l'une des 24 permutations du quadruplet}\;(\sqrt{2},-\sqrt{2},\sqrt{3},-\sqrt{3})
\end{align*}

\end{enumerate}

\begin{align*}\ensuremath 1 & =(X+(1-X))^{n+m-1}=\sum_{k=0}^{n+m-1}C_{n+m-1}^kX^k(1-X)^{n+m-1-k}                                         \\
& =\sum_{k=0}^{n-1}C_{n+m-1}^kX^k(1-X)^{n+m-1-k}
+\sum_{k=n}^{n+m-1}C_{n+m-1}^kX^k(1-X)^{n+m-1-k}                                                                           \\
& =(1-X)^m\sum_{k=0}^{n-1}C_{n+m-1}^kX^k(1-X)^{n-1-k}+X^n\sum_{k=n}^{n+m-1}C_{n+m-1}^kX^{k-n}(1-X)^{n+m-1-k}
\end{align*}

Soient \( U = \sum_{k = n}^{n+m-1}C_{n+m-1}^kX^{k-n}(1-X)^{n+m-1-k} \) et \( V = \sum_{k = 0}^{n-1}C_{n+m-1}^kX^k(1-X)^{n-1-k} \). \( U \) et \( V \) sont des polynômes tels que \( UX^n+V(1-X)^m = 1 \). De plus, pour \( n\le k\le n+m-1 \), \( \mbox{deg}(X^{k-n}(1-X)^{n+m-1-k}) = k-n+n+m-1-k = m-1<m \) et donc \( \mbox{deg}(U)<m \) et de même pour \( 0\le k\le n-1 \), \( \mbox{deg}(X^k(1-X)^{n-1-k}) = k+n-1-k = n-1<n \) et \( \mbox{deg}(V)<n \).

exercices.enonce:
Résoudre dans \( \Cc \) les équations suivantes :
	\begin{enumerate}
		\item \( z^4+2z^3+3z^2+2z+1 = 0 \) en posant \( Z = z+\frac{1}{z} \) (ou autrement).

		\item \( z^6-5z^5+5z^4-5z^2+5z-1 = 0 \).

		\item \( z^7-z^6-7z^5+7z^4+7z^3-7z^2-z+1 = 0 \).
	\end{enumerate}

Résoudre dans \( \Cc^3 \) le système \( \left\{
	\begin{array}{l}
		y^2+yz+z^2 = 7  \\
		z^2+zx+x^2 = 13 \\
		x^2+xy+y^2 = 3
	\end{array}
	\right. \).

exercices.correction:
Si \( (x,y,z) \) est solution du système proposé noté \( (S) \), alors \( x \), \( y \) et \( z \) sont deux à deux distincts. En effet, si par exemple \( x = y \) alors \( 7 = y^2+yz+z^2 = x^2+xz+z^2 = 13 \) ce qui est impossible. Donc,

\[
(S)\Leftrightarrow\left\{
\begin{array}{l}
y^3-z^3 = 7(y-z)  \\
z^3-x^3 = 13(z-x) \\
x^3-y^3 = 3(x-y)
\end{array}
\right..
\]
En additionnant les trois équations, on obtient \( -10x+4y+6z = 0 \) ou encore \( -5x+2y+3z = 0 \). Donc,

\begin{align*}\ensuremath (S) & \Leftrightarrow\left\{
\begin{array}{l}
	y=\frac{1}{2}(5x-3z)                             \\
	(\frac{1}{2}(5x-3z))^2+\frac{1}{2}(5x-3z)z+z^2=7 \\
	z^2+zx+x^2=13                                    \\
	x^2+\frac{1}{2}(5x-3z)x+(\frac{1}{2}(5x-3z))^2=3
\end{array}
\right.\Leftrightarrow\left\{
\begin{array}{l}
	y=\frac{1}{2}(5x-3z) \\
	25x^2-20xz+7z^2=28   \\
	z^2+zx+x^2=13        \\
	39x^2-36xz+9z^2=12
\end{array}
\right.                                                \\
& \Leftrightarrow\left\{
\begin{array}{l}
	y=\frac{1}{2}(5x-3z)         \\
	xz=13-x^2-z^2                \\
	25x^2-20(13-x^2-z^2)+7z^2=28 \\
	39x^2-36(13-x^2-z^2)+9z^2=12
\end{array}
\right.
\Leftrightarrow\left\{
\begin{array}{l}
	y=\frac{1}{2}(5x-3z) \\
	xz=13-x^2-z^2        \\
	5x^2+3z^2=32
\end{array}
\right.
\end{align*}

Soit \( (S') \) le système formé des deux dernières équations. On note que \( x = 0 \) ne fournit pas de solution et donc

\begin{align*}\ensuremath (S') & \Leftrightarrow\left\{
\begin{array}{l}
	z^2=\frac{1}{3}(32-5x^2) \\
	xz=13-x^2-\frac{1}{3}(32-5x^2)
\end{array}
\right.\Leftrightarrow\left\{
\begin{array}{l}
	z=\frac{2x^2+7}{3x} \\
	\frac{(2x^2+7)^2}{9x^2}=\frac{1}{3}(32-5x^2)
\end{array}
\right.
\end{align*}

La deuxième équation s'écrit \( (2x^2+7)^2 = 3x^2(32-5x^2) \) puis \( 19x^4-68x^2+49 = 0 \) puis \( x^2 = \frac{34\pm15}{19} \) D'où les solutions \( x = 1 \) ou \( x = -1 \) ou \( x = \sqrt{\frac{49}{19}} \) ou \( x = -\sqrt{\frac{49}{19}} \). Puis, les quatre triplets solutions du système : \( (1,-2,3) \), \( (-1,2,-3) \), \( (\frac{7}{\sqrt{19}},\frac{1}{\sqrt{19}},\frac{11}{\sqrt{19}}) \) et \( (-\frac{7}{\sqrt{19}},-\frac{1}{\sqrt{19}},-\frac{11}{\sqrt{19}}) \).

exercices.enonce:
Soit \( n \) un entier naturel supérieur ou égal à \( 2 \). Pour \( k\in\Zz \), on pose \( \omega_k = e^{2ik\pi/n} \).
	\begin{enumerate}
		\item Calculer \( \prod_{k = 0}^{n-1}\left(1+\frac{2}{2-\omega_k}\right) \).

		\item Montrer que, pour tout réel \( a \), \( \prod_{k = 0}^{n-1}(\omega_k^2-2\omega_k\cos a+1) = 2(1-\cos(na)) \) (questions indépendantes.)
	\end{enumerate}

exercices.correction:
Soit \( P = \prod_{k = 0}^{n-1}(X-\omega_k) = X^n-1 \) (où \( \omega_k = e^{2ik\pi/n} \))
\begin{enumerate}
\item \( \prod_{k = 0}^{n-1}(1+\frac{2}{2-\omega_k}) = \frac{\prod_{k = 0}^{n-1}(4-\omega_k)}{\prod_{k = 0}^{n-1}(2-\omega_k)} = \frac{P(4)}{P(2)} = \frac{4^n-1}{2^n-1} = 2^n+1 \).

\item

\begin{align*}\ensuremath
	\prod_{k=0}^{n-1}(\omega_k^2-2\omega_k\cos a+1) & =\prod_{k=0}^{n-1}(e^{ia}-\omega_k)(e^{-ia}-\omega_k)=P(e^{ia})P(e^{-ia})=(e^{ina}-1)(e^{-ina}-1) \\
	& =2-e^{ina}-e^{-ina}=2(1-\cos na).
\end{align*}
\end{enumerate}

\begin{enumerate}
