			\item \( X^3-X^2-X-2 \) et \( X^5-2X^4+X^2-X-2 \)

			\item \( X^4+X^3-2X+1 \) et \( X^3+X+1 \)

			\item \( X^5+3X^4+X^3+X^2+3X+1 \) et \( X^4+2X^3+X+2 \)

			\item \( nX^{n+1}-(n+1)X^n+1 \) et \( X^n-nX+n-1 \) (\( n\in\Nn^*) \)
		\end{enumerate}

		\item Calculer le pgcd \( D \) des polynômes \( A \) et \( B \) ci-dessous. Trouver des polynômes \( U \) et \( V \) tels que \( AU+BV = D \).
		\begin{enumerate}
			\item \( A = X^5+3X^4+2X^3-X^2-3X-2 \)\\ et \( B = X^4+2X^3+2X^2+7X+6 \)

			\item \( A = X^6-2X^5+2X^4-3X^3+3X^2-2X \)\\ et \( B = X^4-2X^3+X^2-X+1 \)
		\end{enumerate}
	\end{enumerate}

\begin{enumerate}
		\item Montrer que si \( A \) et \( B \) sont deux polynômes à coefficients dans \( \Qq \), alors le quotient et le reste de la division euclidienne de \( A \) par \( B \), ainsi que \( \pgcd(A,B) \), sont aussi à coefficients dans \( \Qq \).

		\item Soit \( a,b,c\in\Cc^* \) distincts, et \( 0<p<q<r \) des entiers. Montrer que si \( P(X) = (X-a)^p(X-b)^q(X-c)^r \) est à coefficients dans \( \Qq \), alors \( a,b,c \in \Qq \).
