		\end{array}
		\right.
		\Leftrightarrow
		\left\{
		\begin{array}{l}
			y=-\frac{3}{2}x \\
			z=\frac{1}{2}x  \\
			t=0
		\end{array}
		\right..
	\end{align*}

	Donc, \( \mbox{Ker}(u-Id) = \mbox{Vect}(e_2) \) où \( e_2 = (2,-3,1,0) \).

	\item[- Cas \( \lambda = 2 \).] Soit \( (x,y,z,t)\in\Cc^4 \).

	\begin{align*}\ensuremath (x,y,z,t)\in\mbox{Ker}(u-Id) & \Leftrightarrow\left\{
		\begin{array}{l}
