exercices.correction:
L'expression de \( f \) dans la base \( \mathcal{B} \) est la suivante \( f(x,y) = (x-y,0) \). Autrement dit à un vecteur \( \begin{pmatrix}x\\y\end{pmatrix} \) on associe le vecteur \( \begin{pmatrix}x-y\\0\end{pmatrix} \). On note que \( f \) est bien une application linéaire. Cette expression nous permet de calculer les matrices demandées.

Remarque : comme \( \mathcal{B} \) est la base canonique on note \( \begin{pmatrix}x\\y\end{pmatrix} \) pour \( \begin{pmatrix}x\\y\end{pmatrix}_\mathcal{B} \) qui est le vecteur \( x \vec{i}+y\vec{j} \).

\begin{enumerate}
\item Calcul de \( \textrm{Mat}(f,\mathcal{B},\mathcal{B}) \). Comme \( \mathcal{B} = (\vec{i}, \vec{j}) \), la matrice s'obtient en calculant \( f(\vec{i}) \) et \( f(\vec{j}) \) :
\[
f(\vec{i}) = f\begin{pmatrix}1\\0\end{pmatrix} = \begin{pmatrix}1\\0\end{pmatrix} = \vec{i}
\quad f(\vec{j}) = f\begin{pmatrix}0\\1\end{pmatrix} = \begin{pmatrix}-1\\0\end{pmatrix} = -\vec{i}
\]
donc
\[
\textrm{Mat}(f,\mathcal{B},\mathcal{B}) = \begin{pmatrix} 1 & -1 \\ 0 & 0 \end{pmatrix}
\]

\item On garde la même application linéaire mais la base de départ change (la base d'arrivée reste \( \mathcal{B} \)). Si on note \( \vec{u} = \vec{i}-\vec{j} \) et \( \vec{v} = -2\vec{i}+3\vec{j} \), on a \( \mathcal{B'} = (\vec{i} - \vec{j}, -2\vec{i}+3\vec{j}) = (\vec{u},\vec{v}) \). On exprime \( f(\vec{u}) \) et \( f(\vec{v}) \) dans la base d'arrivée \( \mathcal{B} \).
\[
f(\vec{u}) = f(\vec{i}- \vec{j}) = f\begin{pmatrix}1\\-1\end{pmatrix} = \begin{pmatrix}2\\0\end{pmatrix}
\quad f(\vec{v}) = f(-2\vec{i}+3\vec{j}) = f\begin{pmatrix}-2\\3\end{pmatrix} = \begin{pmatrix}-5\\0\end{pmatrix}
\]
donc
\[
\textrm{Mat}(f,\mathcal{B}',\mathcal{B}) = \begin{pmatrix} 2 & -5 \\ 0 & 0 \end{pmatrix}
\]

\item Toujours avec le même \( f \) on prend \( \mathcal{B}' \) comme base de départ et d'arrivée, il s'agit donc d'exprimer \( f(\vec{u}) \) et \( f(\vec{v}) \) dans la base \( \mathcal{B}' = (\vec{u},\vec{v}) \). Nous venons de calculer que
\[
f(\vec{u}) = f(\vec{i}- \vec{j}) = f\begin{pmatrix}1\\-1\end{pmatrix} = \begin{pmatrix}2\\0\end{pmatrix} = 2\vec{i}
\quad f(\vec{v}) = f(-2\vec{i}+3\vec{j}) = f\begin{pmatrix}-2\\3\end{pmatrix} = \begin{pmatrix}-5\\0\end{pmatrix} = -5\vec{i}
\]
Mais il nous faut obtenir une expression en fonction de la base \( \mathcal{B}' \). Remarquons que
\[
\left\{\begin{array}{lcr}
	\vec{u} & = & \vec{i}-\vec{j}    \\
	\vec{v} & = & -2\vec{i}+3\vec{j}
\end{array}\right.
\implies
\left\{\begin{array}{lcr}
	\vec{i} & = & 3\vec{u}+\vec{v} \\
	\vec{j} & = & 2\vec{u}+\vec{v}
\end{array}\right.
\]
Donc
\[
f(\vec{u}) = f(\vec{i}- \vec{j}) = 2\vec{i} = 6\vec{u}+2\vec{v} = \begin{pmatrix}6\\2\end{pmatrix}_{\mathcal{B}'}
\quad f(\vec{v}) = f(-2\vec{i}+3\vec{j}) = -5\vec{i} = -15\vec{u}-5\vec{v} = \begin{pmatrix}-15\\-5\end{pmatrix}_{\mathcal{B}'}
\]
Donc
\[
\textrm{Mat}(f,\mathcal{B}',\mathcal{B}') = \begin{pmatrix} 6 & -15 \\ 2 & -5 \end{pmatrix}
\]
Remarque : \( \begin{pmatrix}x\\y\end{pmatrix}_{\mathcal{B}'} \) désigne le vecteur \( x \vec{u}+y\vec{v} \).
\end{enumerate}

exercices.enonce:
\label{exo1093}
	Soit \( E \) un espace vectoriel et \( f \) une application linéaire de \( E \) dans lui-même telle que \( f^2 = f \).
	\begin{enumerate}
		\item Montrer que \( E = \ker f \oplus \Im f \).

		\item Supposons que \( E \) soit de dimension finie \( n \). Posons \( r = \dim \Im f \). Montrer qu'il existe une base \( \mathcal{B} = ( e_1, \ldots ,e_n) \) de \( E \) telle que : \( f(e_i) = e_i \) si \( i\le r \) et \( f(e_i) = 0 \) si \( i>r \). Déterminer la matrice de \( f \) dans cette base \( \mathcal{B} \).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Nous devons montrer \( \ker f \cap \Im f = \{0\} \) et \( \ker f + \Im f = E \).
\begin{enumerate}
	\item Si \( x \in \ker f \cap \Im f \) alors d'une part \( f(x) = 0 \) et d'autre part il existe \( x'\in E \) tel que \( x = f(x') \). Donc \( 0 = f(x) = f\big(f(x')\big) = f(x') = x \) donc \( x = 0 \) (on a utilisé \( f\circ f = f \)). Donc \( \ker f \cap \Im f = \{0\} \).

	\item Pour \( x\in E \) on le réécrit \( x = x-f(x) + f(x) \). Alors \( x-f(x) \in \ker f \) (car \( f\big(x-f(x) \big) = f(x)-f\circ f (x) = 0 \)) et \( f(x)\in \Im f \). Donc \( x \in \ker f + \Im f \). Donc \( \ker f + \Im f = E \).

	\item Conclusion : \( E = \ker f \oplus \Im f \).
\end{enumerate}

\item Notons \( r \) le rang de \( f \) : \( r = \dim \Im f \). Soit \( \{e_1,\ldots,e_r\} \) une base de \( \Im f \) et soit \( \{e_{r+1},\ldots, e_n\} \) une base de \( \ker f \). Comme \( E = \ker f \oplus \Im f \) alors \( (e_1,\ldots ,e_n) \) est une base de \( E \). Pour \( i > r \) alors \( e_i \in \ker f \) donc \( f(e_i) = 0 \).

Comme \( f\circ f = f \) alors pour n'importe quel \( x\in \Im f \) on a \( f(x) = x \) : en effet comme \( x\in \Im f \), il existe \( x'\in E \) tel que \( x = f(x') \) ainsi \( f(x) = f\big(f(x')\big) = f(x') = x \). En particulier si \( i\le r \) alors \( f(e_i) = e_i \).

\item La matrice de \( f \) dans la base \( (e_1,\ldots,e_n) \) est donc :
\[
\begin{pmatrix}
	I   & (0) \\
	(0) & (0)
\end{pmatrix}
\]
où \( I \) désigne la matrice identité de taille \( r\times r \) et les \( (0) \) désignent des matrices nulles.

\end{enumerate}

\begin{enumerate}
\item
\begin{enumerate}
	\item Commençons par des remarques élémentaires : la matrice est non nulle donc \( \textrm{rg}(A) \ge 1 \) et comme il y a \( p = 4 \) lignes et \( n = 3 \) colonnes alors \( \textrm{rg}(A) \le \min(n,p) = 3 \).

	\item Ensuite on va montrer \( \textrm{rg}(A) \ge 2 \) en effet le sous-déterminant \( 2\times 2 \) (extrait du coin en haut à gauche) : \( \begin{vmatrix}
		1 & 2 \\
		3 & 4
	\end{vmatrix} = -2 \) est non nul.

	\item Montrons que \( \textrm{rg}(A) = 2 \). Avec les déterminants il faudrait vérifier que pour toutes les sous-matrices \( 3\times 3 \) les déterminants sont nuls. Pour éviter de nombreux calculs on remarque ici que les colonnes sont liées par la relation \( v_2 = v_1+v_3 \). Donc \( \textrm{rg}(A) = 2 \).

	\item L'application linéaire associée à la matrice \( A \) est l'application \( f_A : \Rr^3 \to \Rr^4 \). Et le théorème du rang \( \dim \ker f_A+ \dim \Im f_A = \dim \Rr^3 \) donne ici \( \dim \ker f_A = 3 - \textrm{rg}(A) = 1 \).

	Mais la relation \( v_2 = v_1+v_3 \) donne immédiatement un élément du noyau : en écrivant \( v_1-v_2+v_3 = 0 \) alors \( A\begin{pmatrix}1\\-1\\1\end{pmatrix} = \begin{pmatrix}0\\0\\0\end{pmatrix} \) Donc \( \begin{pmatrix}1\\-1\\1\end{pmatrix} \in \ker f_A \). Et comme le noyau est de dimension \( 1 \) alors
	\[
	\ker f_A = \textrm{Vect} \begin{pmatrix}1\\-1\\1\end{pmatrix}
	\]

	\item Pour une base de l'image, qui est de dimension \( 2 \), il suffit par exemple de prendre les deux premiers vecteurs colonnes de la matrice \( A \) (ils sont clairement non colinéaires) :
	\[
	\Im f_A = \textrm{Vect} \left\{ v_1, v_2 \right\} =
	\textrm{Vect} \left\{ \begin{pmatrix}1\\3\\5\\7\end{pmatrix}, \begin{pmatrix}1\\1\\1\\1\end{pmatrix} \right\}
	\]
\end{enumerate}

\item On fait le même travail avec \( B \) et \( f_B \).
\begin{enumerate}
	\item Matrice non nulle avec \( 4 \) lignes et \( 4 \) colonnes donc \( 1 \le \textrm{rg}(B) \le 4 \).

	\item Comme le sous-déterminant (du coin supérieur gauche) \( \begin{vmatrix}
		2 & 2 \\
		4 & 3
	\end{vmatrix} = -2 \) est non nul alors \( \textrm{rg}(B) \ge 2 \).

	\item Et pareil avec le sous-déterminant \( 3\times 3 \) :
	\[
	\begin{vmatrix}
		2 & 2  & -1 \\
		4 & 3  & -1 \\
		0 & -1 & 2
	\end{vmatrix} = -2
	\]
	qui est non nul donc \( \textrm{rg}(B) \ge 3 \).

	\item Maintenant on calcule le déterminant de la matrice \( B \) et on trouve \( \det B = 0 \), donc \( \textrm{rg}(B) < 4 \). Conclusion \( \textrm{rg}(B) = 3 \). Par le théorème du rang alors \( \dim \ker f_B = 1 \).

	\item Cela signifie que les colonnes (et aussi les lignes) sont liées, comme il n'est pas clair de trouver la relation à la main on résout le système \( B X = 0 \) pour trouver cette relation ; autrement dit :
	\[
	\begin{pmatrix}
		2 & 2  & -1 & 7  \\
		4 & 3  & -1 & 11 \\
		0 & -1 & 2  & -4 \\
		3 & 3  & -2 & 11
	\end{pmatrix}
	\cdot
	\begin{pmatrix} x\\y\\z\\t \end{pmatrix} =
	\begin{pmatrix} 0\\0\\0\\0 \end{pmatrix}
	\text{ ou encore }
	\left\{
	\begin{array}{rcl}
		2x + 2y -z + 7t  & = & 0 \\
		4x + 3y -z + 11t & = & 0 \\
		-y +2z -4t       & = & 0 \\
		3x + 3y -2z+ 11t & = & 0
	\end{array}
	\right.
	\]
	Après résolution de ce système on trouve que les solutions s'écrivent \( (x,y,z,t) = (-\lambda,-2\lambda,\lambda,\lambda) \). Et ainsi
	\[
	\ker f_B = \textrm{Vect} \begin{pmatrix}-1\\-2\\1\\1\end{pmatrix}
	\]
	Et pour une base de l'image il suffit, par exemple, de prendre les \( 3 \) premiers vecteurs colonnes \( v_1,v_2,v_3 \) de la matrice \( B \), car ils sont linéairement indépendants :
	\[
	\Im f_B = \textrm{Vect} \left\{ v_1, v_2, v_3 \right\} =
	\textrm{Vect} \left\{
	\begin{pmatrix}2\\4\\0\\3\end{pmatrix},
	\begin{pmatrix}2\\3\\-1\\3\end{pmatrix},
	\begin{pmatrix}-1\\-1\\2\\-2\end{pmatrix}
	\right\}
	\]
\end{enumerate}
\end{enumerate}

