exercices.correction:
\begin{enumerate}
\item Soit \( \varepsilon>0 \) donné. Puisque \( f \) est Riemann-intégrable sur \( [a,b] \), il existe une subdivision \( \sigma_1 = \{a_0 = a< a_1< \dots< a_n = b\} \) de \( [a, b] \) telle que \( \overline{S}_f^{\sigma_1}\le\underline{S}_f^{\sigma_1} +
\frac{\varepsilon}{2} \). Puisque \( g \) est Riemann-intégrable sur \( [a,b] \), il existe une subdivision \( \sigma_2 = \{b_0 = a< b_1<
\dots< b_p = b\} \) de \( [a, b] \) telle que \( \overline{S}_g^{\sigma_2}\le\underline{S}_g^{\sigma_2} +
\frac{\varepsilon}{2} \). On note \( \sigma_1\cup\sigma_2 = \{c_0 = a< c_1 < \dots < c_{q-1} < c_q = b\} \) la subdivision de \( [a,b] \) obtenue en ordonnant l'ensemble \( \{a_0, \dots, a_n, b_0,
\dots, b_n\} \) par ordre croissant, puis en identifiant les points qui apparaissent plusieurs fois (on obtient une subdivision de \( [a,b] \) en \( q \) intervalles avec \( max\{n, p\}\le q \le n+p \)). Puisque \( \sigma_1\cup\sigma_2 \) est une subdivision \emph{plus fine} que \( \sigma_1 \), on a :
\begin{equation}\label{1}
	\overline{S}_f^{\sigma_1\cup\sigma_2}\, \le\,\,
	\overline{S}_f^{\sigma_1}\quad\quad\text{et}\quad\quad
	\underline{S}_f^{\sigma_1}\le\,\,
	\underline{S}_f^{\sigma_1\cup\sigma_2}.
\end{equation}
De même,
\begin{equation}\label{2}
	\overline{S}_g^{\sigma_1\cup\sigma_2}\, \le\,\,
	\overline{S}_g^{\sigma_2}\quad\quad\text{et}\quad\quad
	\underline{S}_g^{\sigma_2}\le\,\,
	\underline{S}_g^{\sigma_1\cup\sigma_2}.
\end{equation}
De plus, sur un intervalle \( ]c_{k-1}, c_k[ \) donné, on a :
\begin{eqnarray*}
	\sup\{f(x) + g(x), \,x \in \,]c_{k-1}, c_k[\} &\le &
	\sup\{f(x), \,x \in \,]c_{k-1}, c_k[\} \\& &+ \sup\{g(x), \,x
	\in \,]c_{k-1}, c_k[\}.
\end{eqnarray*}
De même :
\begin{eqnarray*}
	\inf\{f(x) + g(x), \,x \in \,]c_{k-1}, c_k[\} & \ge &
	\inf\{f(x),\,x \in \,]c_{k-1}, c_k[\}\\ & & + \inf\{g(x), \,x
	\in \,]c_{k-1}, c_k[\}.
\end{eqnarray*}
On en déduit que :
\begin{equation}\label{3}
	\overline{S}_{f+g}^{\sigma_1\cup\sigma_2} \,\le\,
	\overline{S}_f^{\sigma_1\cup\sigma_2}\,+\,\overline{S}_g^{\sigma_1\cup\sigma_2},
\end{equation}
et
\begin{equation}\label{4}
	\underline{S}_f^{\sigma_1\cup\sigma_2}\,+\,
	\underline{S}_g^{\sigma_1\cup\sigma_2} \,\le\,
	\underline{S}_{f+g}^{\sigma_1\cup\sigma_2}.
\end{equation}
En utilisant les inégalités \eqref{1}, \eqref{2}, \eqref{3} et
\eqref{4}, il vient alors :
\begin{equation*}
	\overline{S}_{f+g}^{\sigma_1\cup\sigma_2}\,\le\,
	\overline{S}_f^{\sigma_1}+
	\overline{S}_g^{\sigma_2}\,\le\,
	\underline{S}_f^{\sigma_1} + \underline{S}_g^{\sigma_2} +
	\varepsilon \le \underline{S}_{f+g}^{\sigma_1\cup\sigma_2} +
	\varepsilon.
\end{equation*}
D'après le théorème rappelé en introduction, on en déduit que \( f+g \) est Riemann-intégrable sur \( [a, b] \). De plus, de l'inégalité
\begin{equation*}
	\underline{S}_f^{\sigma_1} + \underline{S}_g^{\sigma_2}
	\le \underline{S}_{f+g}^{\sigma_1\cup\sigma_2},
\end{equation*}
on déduit que
\begin{equation*}
	\sup_{\sigma_1, \sigma_2}\left(\underline{S}_f^{\sigma_1} +
	\underline{S}_g^{\sigma_2} \right) \le \sup_{\sigma_1,
		\sigma_2}\underline{S}_{f+g}^{\sigma_1\cup\sigma_2}.
\end{equation*}
Or
\[
\sup_{\sigma_1,
	\sigma_2}\left(\underline{S}_f^{\sigma_1} +
\underline{S}_g^{\sigma_2} \right) =
\sup_{\sigma_1}\underline{S}_f^{\sigma_1} +
\sup_{\sigma_2}\underline{S}_g^{\sigma_2} = \int_a^b f(x)\,dx + \int_a^b g(x)\,dx
\]
et
\[
\sup_{\sigma_1,
	\sigma_2}\underline{S}_{f+g}^{\sigma_1\cup\sigma_2} =
\sup_{\sigma}\underline{S}_{f+g}^{\sigma} = \int_a^b\left(f(x) + g(x)\right)\,dx.
\]
Ainsi
\begin{equation*}
	\int_a^b f(x)\,dx + \int_a^b g(x)\,dx \le \int_a^b\left(f(x) + g(x)\right)\,dx.
\end{equation*}
De même, l'inégalité
\begin{equation*}
	\overline{S}_{f+g}^{\sigma_1\cup\sigma_2}\,\le\,
	\overline{S}_f^{\sigma_1}+ \overline{S}_g^{\sigma_2}
\end{equation*}
implique \( \int_a^b\left(f(x) + g(x)\right)\,dx \le
\int_a^b f(x)\,dx + \int_a^b g(x)\,dx \). En conclusion, \( \int_a^b\left(f(x) + g(x)\right)\,dx = \int_a^b f(x)\,dx + \int_a^b g(x)\,dx \).

\item \( \cdot \) Pour \( \lambda = 0 \) il n'y a rien a démontrer. \\
\( \cdot \) Si \( f \) est Riemann-intégrable sur \( [a,b] \) et \( \lambda > 0 \), alors pour tout subdivision \( \sigma = \{a_0 = a<\dots<a_n = b\} \) de \( [a,b] \), on a:
\begin{eqnarray*}
	\inf\{\lambda f(x),\,x \in\,]a_{k-1},a_k[\,\} = \lambda
	\inf\{f(x),\,x \in\,]a_{k-1},a_k[\,\}\\
	\sup\{\lambda f(x),\,x \in\,]a_{k-1},a_k[\,\} = \lambda
	\sup\{f(x),\,x \in\,]a_{k-1},a_k[\,\}.
\end{eqnarray*}
Par conséquent, \( \underline{S}_{\lambda f}^{\sigma} = \lambda
\underline{S}_f^{\sigma} \) et \( \overline{S}_{\lambda f}^{\sigma} = \lambda \overline{S}_f^{\sigma} \). On en déduit que
\begin{equation*}
	\sup_{\sigma}\underline{S}_{\lambda f}^{\sigma} = \lambda
	\sup_{\sigma}\underline{S}_f^{\sigma} = \lambda \int_a^b f(x)\,dx = \lambda \inf_{\sigma}\overline{S}_f^{\sigma} =
	\inf_{\sigma}\overline{S}_{\lambda f}^{\sigma}.
\end{equation*}
En conclusion, \( \lambda f \) est Riemann-intégrable et \( \int_a^b \lambda f(x)\,dx = \lambda \int_a^b f(x)\,dx \).\\
\( \cdot \) Si \( f \) est Riemann-intégrable sur \( [a,b] \) et \( \lambda <0 \), alors pour tout subdivision \( \sigma = \{a_0 = a<\dots<a_n = b\} \) de \( [a,b] \), on a:
\begin{eqnarray*}
	\inf\{\lambda f(x),\,x \in\,]a_{k-1},a_k[\,\} = \lambda
	\sup\{f(x),\,x \in\,]a_{k-1},a_k[\,\}\\
	\sup\{\lambda f(x),\,x \in\,]a_{k-1},a_k[\,\} = \lambda
	\inf\{f(x),\,x \in\,]a_{k-1},a_k[\,\}.
\end{eqnarray*}
Par conséquent, \( \underline{S}_{\lambda f}^{\sigma} = \lambda
\overline{S}_f^{\sigma} \) et \( \overline{S}_{\lambda f}^{\sigma} = \lambda \underline{S}_f^{\sigma} \). On en déduit que
\begin{equation*}
	\sup_{\sigma}\underline{S}_{\lambda f}^{\sigma} = \lambda
	\inf_{\sigma}\overline{S}_f^{\sigma} = \lambda \int_a^b f(x)\,dx = \lambda \sup_{\sigma}\underline{S}_f^{\sigma} =
	\inf_{\sigma}\overline{S}_{\lambda f}^{\sigma}.
\end{equation*}
En conclusion, \( \lambda f \) est Riemann-intégrable et \( \int_a^b \lambda f(x)\,dx = \lambda \int_a^b f(x)\,dx \).

\item Soient \( f \) et \( g \) deux fonctions Riemann-intégrables sur \( [a,b] \) telles que, pour tout \( t\in [a,b] \), \( f(t)\le g(t) \). Soit \( \sigma = \{a_0 = a< \dots < a_n = b\} \) une subdivision de \( [a,b] \). Alors
\begin{equation*}
	\inf\{f(x), \, x \in\, ]a_{k-1}, a_k[\,\} \le \inf\{g(x), \, x
	\in\, ]a_{k-1}, a_k[\,\}.
\end{equation*}
Il en découle que
\begin{equation*}
	\sup_{\sigma} \underline{S}_f^{\sigma} \le \sup_{\sigma}
	\underline{S}_f^{\sigma},
\end{equation*}
c'est-à-dire \( \int_a^b f(x)\,dx \le \int_a^b g(x)\,dx \).

\item Soit \( \{f_i\}_{i\in\Nn} \) une suite de fonctions Riemann-intégrables, qui converge uniformément vers \( f \) sur \( [a, b] \). Soit \( \varepsilon>0 \) donné. Il existe \( N>0 \) tel que \( \forall i> N \), \( \sup_{[a, b]}|f_i(t) - f(t)| < \varepsilon \). En particulier, \( f_i(t) - \varepsilon < f(t) < f_i(t) +
\varepsilon \). Pour un tel \( i \), on en déduit que pour toute subdivision \( \sigma = \{a_0 = a < \dots < a_n = b\} \), on a
\begin{eqnarray*}
	\sup_{]a_{k-1}, a_k[}f \,\le \,\sup_{]a_{k-1}, a_k[}f_i +
	\varepsilon\quad \text{et}\quad \inf_{]a_{k-1}, a_k[}f \ge
	\inf_{]a_{k-1}, a_k[}f_i - \varepsilon
\end{eqnarray*}
En particulier :
\begin{eqnarray*}
	\sup_{]a_{k-1}, a_k[}f - \inf_{]a_{k-1}, a_k[}f\,\le\,
	\sup_{]a_{k-1}, a_k[}f_i - \inf_{]a_{k-1}, a_k[}f_i + 2\varepsilon.
\end{eqnarray*}
Il en découle que :
\begin{equation*}
	\overline{S}_f^{\sigma} - \underline{S}_f^{\sigma}\, \le\,
	\overline{S}_{f_i}^{\sigma} - \underline{S}_{f_i}^{\sigma} + 2\varepsilon (b- a).
\end{equation*}
Comme \( f_i \) est Riemann-intégrable, d'après le théorème de l'introduction, il existe une subdivision \( \sigma \) de \( [a, b] \) telle que \( \overline{S}_{f_i}^{\sigma} - \underline{S}_{f_i}^{\sigma}
\le \varepsilon \). On en déduit que
\begin{equation*}
	\overline{S}_f^{\sigma} - \underline{S}_f^{\sigma} \le
	\varepsilon \left(1 + 2(b-a)\right),
\end{equation*}
ce qui implique que \( f \) est Riemann-intégrable.
\end{enumerate}

Soit \( f \) une fonction croissante \( [a,b] \). Pour montrer que \( f \) est Riemann-intégrable, il suffit de trouver, pour tout \( \varepsilon>0 \) donné, une subdivision de \( [a, b] \) telle que \( \overline{S}_f^{\sigma} - \underline{S}_f^{\sigma} <
\varepsilon \). Soit \( \sigma = \{a_0 = a < \dots < a_n = b\} \) la subdivision régulière de \( [a,b] \), de pas \( \left(\frac{b-a}{n}\right) \). On a
\begin{equation*}
\inf_{]a_{k-1}, a_k[} f = f(a_{k-1}) \quad \text{et} \quad
\sup_{]a_{k-1}, a_k[} f = f(a_k).
\end{equation*}
Ainsi :
\begin{eqnarray*}
\overline{S}_f^{\sigma} - \underline{S}_f^{\sigma} &=&
\sum_{k=1}^n (a_k - a_{k-1})\left( f(a_k) - f(a_{k-1})
\right) \\ &= &\left(\frac{b-a}{n}\right) \sum_{k=1}^n\left( f(a_k) - f(a_{k-1}) \right)\\& =&
\left(\frac{b-a}{n}\right)\left(f(b)- f(a)\right).
\end{eqnarray*}
Pour \( n \) assez grand, la subdivision régulière de \( [a,b] \) satisfait \( \overline{S}_f^{\sigma} - \underline{S}_f^{\sigma}
< \varepsilon \). D'autre part, si \( g \) est décroissante, \( f = -g \) est croissante, donc \( g \) est Riemann-intégrable par l'exercice précédent (question 2.) avec \( \lambda = -1 \).

Une fonction \( f \) continue sur \( [a, b] \) est uniformément continue sur \( [a, b] \). En particulier, pour tout \( \varepsilon>0 \), il existe \( n>0 \) tel que
\begin{equation*}
|x - y| < \left(\frac{b-a}{n}\right) \Rightarrow |f(x) - f(y)|<
\varepsilon.
\end{equation*}
Soit \( \sigma = \{a_0 = a < \dots < a_n = b\} \) la subdivision régulière de \( [a,b] \), de pas \( \left(\frac{b-a}{n}\right) \). On a :
\begin{equation*}
\sup_{]a_{k-1}, a_k[} f - \inf_{]a_{k-1}, a_k[} f \le 2\varepsilon.
\end{equation*}
Il vient alors :
\begin{equation*}
\overline{S}_f^{\sigma} - \underline{S}_f^{\sigma} \le
\left(\frac{b-a}{n}\right)\sum_{k=1}^n 2 \varepsilon = (b-a) 2\varepsilon,
\end{equation*}
ce qui permet de conclure grâce au théorème de l'introduction que \( f \) est Riemann-intégrable sur \( [a,b] \).

exercices.enonce:
On dit qu'une partie \( A \) de \( \Rr \) est \emph{négligeable}
	si, pour tout nombre réel \( \varepsilon>0 \), il existe une suite \( (I_n)_{n\in\Nn} \) d'intervalles \( I_n = ]a_n,b_n[ \) telle que :
	\begin{equation*}
		A \subset \bigcup_{n\in\Nn}I_n\quad \text{et}\quad
		\sum_{n\in\Nn}(b_n-a_n)\le\varepsilon.
	\end{equation*}
	\begin{enumerate}
		\item Montrer qu'une réunion dénombrable d'ensembles négligeables est un ensemble négligeable. \item Montrer qu'une fonction bornée \( f :[a,b]\rightarrow\Rr \) est intégrable au sens de Riemann sur \( [a,b] \) si et seulement si l'ensemble des points où \( f \) n'est pas continue est \emph{négligeable}.
	\end{enumerate}

Pour tout \( n\in\Nn \), on définit \( f_n :]0,1]\rightarrow\Rr \) par : \( f_n(x) = n e^{-nx} \). Montrer que la suite \( (f_n)_{n\in\Nn} \) converge simplement vers une fonction \( f \) sur \( ]0,1] \) mais que
	\begin{equation*}
		\int_0^1\lim_{n\rightarrow+\infty}f_n(x)\,dx \quad\neq\quad
		\lim_{n\rightarrow+\infty}\int_0^1f_n(x)\,dx.
	\end{equation*}
	Vérifier que la convergence de \( (f_n)_{n\in\Nn} \) vers \( f \) n'est pas \emph{uniforme} sur \( ]0,1] \).

exercices.correction:
Pour tout \( n\in\Nn \), on définit \( f_n:]0,1]\rightarrow\Rr \) par : \( f_n(x) = n e^{-nx} \). Pour tout \( x\in]0,1] \), on a \( \lim_{n\rightarrow+\infty}f_n(x) = \lim_{n\rightarrow+\infty}ne^{-nx} = 0 \). On en déduit que la suite de fonctions \( f_n \) converge ponctuellement (ou
\emph{simplement}) vers la fonction identiquement nulle \( f\equiv0 \). On a \( \int_0^1f(x)\,dx = 0 \) mais
\begin{equation*}
\int_0^1 f_n(x)\,dx = 1- e^{-n},
\end{equation*}
et \( \lim_{n\rightarrow+\infty}\int_0^1f_n(x)\,dx = 1 \). La suite \( (f_n)_{n\in\Rr} \) ne converge pas uniformément vers \( f \) sur \( ]0,1] \), car pour tout \( \varepsilon>0 \), et pour tout \( n\in\Nn \), on a :
\begin{equation*}
\sup_{]0, -\frac{1}{n}\log\left(\frac{\varepsilon}{n}\right)[}|f_n(x)-f(x)| > \varepsilon.
\end{equation*}

