	z-2 & -3 & 2
\end{array}
\right|=0\Leftrightarrow13x-5(y+1)+(z-2)=0\Leftrightarrow13x-5y+z=7.
\end{align*}

\begin{center}
\shadowbox{ La projetée orthogonale de \( (D) \) sur \( (P) \) est la droite d'équations \( \left\{
	\begin{array}{l}
		13x-5y+z = 7 \\
		x+3y+2z = 6
	\end{array}
	\right. \). }
