\end{center}

\item On constate, en utilisant la formule \( \sin^2t = 1-\cos^2t = -1-x(t) \), que
\begin{eqnarray*}
	y(t)&=&\sin^4t+4\sin^2t+4=(-1-x(t))^2+4(-1-x(t))+4\\
	&=&x(t)^2-2x(t)+1 = (x(t)-1)^2
\end{eqnarray*}
Ainsi les points \( (x,y) \) de la courbe vérifient l'équation \( y = (x-1)^2 \). De plus, lorsque le paramètre \( t \) décrit \( \Rr \), \( x(t) = \cos^2t-2 \) décrit l'intervalle \( [-2;-1] \). Finalement,
\begin{eqnarray*}
	(x,y)\in\mathcal{C}&\Longleftrightarrow&\exists\, t\in\Rr\ |\ \left\{\begin{array}{l}
		x(t)=\cos^2t-2 \\
		y(t)=\sin^4t+4\sin^2t+4
	\end{array}\right.\\
	\ &\Longleftrightarrow&\left\{\begin{array}{l}
		x\in[-2;-1] \\
		y=(x-1)^2
	\end{array}\right.
\end{eqnarray*}
et la courbe est donc le graphe de la fonction
\[
\begin{array}{rccc}
	f: & [-2;-1] & \to     & \Rr     \\
	\  & x       & \mapsto & (x-1)^2
\end{array}
\]
