			\begin{array}{ccccccccccc}
				\alpha_0 & + & \alpha_1 \lambda_1 & + & \alpha_2 \lambda_1^2 & + & ... & + & \alpha_{n-1}\lambda_1^{n-1}
				& = & 0                                                                                                     \\
