exercices.enonce:
Soit \( E = \Rr_{2n-1}[X] \), et \( x_1,\dots,x_n \in \Rr \) distincts. On note :
	\[
	{\phi_i} : E\to \Rr, P \mapsto {P(x_i)} ;
	\qquad {\psi_i} : E \to \Rr, P \mapsto {P'(x_i)}
	\]
	\begin{enumerate}
		\item Montrer que \( (\phi_1,\dots,\phi_n,\psi_1,\dots,\psi_n) \) est une base de \( E^* \).

		\item Chercher la base duale. On notera \( P_i = \prod_{j\ne i}\frac{X-x_j}{x_i-x_j} \) et \( d_i = P_i'(x_i) \).

	\end{enumerate}

Soit \( E = \Rr_3[X] \). On considère les formes linéaires : \( f_i : P \mapsto \int_{t = -1}^1 t^iP(t)\,d t \).

	\begin{enumerate}
		\item Montrer que \( (f_0,f_1,f_2,f_3) \) est une base de \( E^* \).

		\item Trouver la base duale.
	\end{enumerate}

Soit \( E = K_n[X] \). On note \( P_0 = 1 \), \( P_i = X(X-1)\cdots(X-i+1) \) pour \( i\ge1 \), et \( f_i : P \mapsto P(i) \).

	\begin{enumerate}
		\item Montrer que \( (P_0,\dots,P_n) \) est une base de \( E \) et \( {\cal B} = (f_0,\dots,f_n) \) est une base de \( E^* \).

		\item Décomposer la forme linéaire \( P_n^* \) dans la base \( \cal B \). (On pourra utiliser les polynômes : \( Q_i = \prod_{1\le j\le n; j\ne i}(X-j) \))

		\item Décomposer de même les autres formes linéaires \( P_k^* \).

	\end{enumerate}

Soit \( E \) l'ensemble des suites \( u = (u_n) \) à termes réels telles que pour tout \( n \) : \( u_{n+2} = u_{n+1} + u_n \).

	\begin{enumerate}
		\item Montrer que \( E \) est un \( \Rr \)-ev de dimension finie.

		\item Soient \( {f_0} : E \to \Rr, u \mapsto {u_0} \) et \( {f_1} : E \to \Rr, u \mapsto {u_1.} \) Trouver la base duale de \( (f_0,f_1) \).

	\end{enumerate}

exercices.correction:
Si \( x \) est colinéaire à \( k \), \( r(x) = x \), et si \( x\in k^\bot,\;r(x) = (\cos\theta)x+(\sin\theta)k\wedge x \). Soit \( x\in E \). On écrit \( x = x_1+x_2 \) où \( x_1\in k^\bot \) et \( x_2\in\mbox{Vect}(k) \). On a \( x_2 = (x.k)k \) (car \( k \) est unitaire) et \( x_1 = x-(x.k)k \). Par suite,

\begin{align*}\ensuremath r(x) & =r(x_1)+r(x_2)=(\cos\theta)x_1+(\sin\theta)k\wedge x_1+x_2=(\cos\theta)(x-(x.k)k)+(\sin\theta)k\wedge x+(x.k)k                         \\
& =(\cos\theta)x+(1-\cos\theta)(x.k)k+sin\theta(k\wedge x)=(\cos\theta)x+2\sin^2\left(\frac{\theta}{2}\right)(x.k)k+sin\theta(k\wedge x)
\end{align*}
\textbf{Application.} Si \( k = \frac{1}{\sqrt{2}}(e_1+e_2) \) et \( \theta = \frac{\pi}{3} \), pour tout vecteur \( x \), on a :

\[
r(x) = \frac{1}{2}x+\frac{1}{2}(x.k)k+\frac{\sqrt{3}}{2}(k\wedge x),
\]
puis, \( r(e_1) = \frac{1}{2}e_1+\frac{1}{4}(e_1+e_2)-\frac{\sqrt{3}}{2\sqrt{2}}e_3 = \frac{1}{4}(3e_1+e_2-\sqrt{6}e_3) \)

\( r(e_2) = \frac{1}{2}e_2+\frac{1}{4}(e_1+e_2)+\frac{\sqrt{3}}{2\sqrt{2}}e_3 = \frac{1}{4}(e_1+3e_2+\sqrt{6}e_3) \)

\( r(e_3) = \frac{1}{2}e_3+\frac{\sqrt{3}}{2\sqrt{2}}(-e_2+e_1) = \frac{1}{4}(\sqrt{6}e_1-\sqrt{6}e_2+2e_3) \).

\begin{center}
\shadowbox{ La matrice cherchée est \( \frac{1}{4}\left(
	\begin{array}{ccc}
		3         & 1        & \sqrt{6}  \\
		1         & 3        & -\sqrt{6} \\
		-\sqrt{6} & \sqrt{6} & 2
	\end{array}
	\right) \). }
	\end{center}

L'application \( (f,g)\mapsto\int_0^1f(t)g(t)\;dt \) est un produit scalaire sur \( C^0([0,1],\Rr) \). D'après l'inégalité de \textsc{Cauchy}-\textsc{Schwarz},

	\begin{align*}\ensuremath I_nI_{n+2} & =\int_0^1f^n(t)\;dt\int_0^1f^{n+2}(t)\;dt=\int_0^1\left(\sqrt{(f(t))^n}\right)^2\;dt\int_0^1\left(\sqrt{(f(t))^{n+2}}\right)^2\;dt \\
& \ge\left(\int_0^1\sqrt{(f(t))^n}\sqrt{(f(t))^{n+2}}\;dt\right)^2=\left(\int_0^1f^{n+1}(t)\;dt\right)^2=I_{n+1}^2
\end{align*}
Maintenant, comme \( f \) est continue et strictement positive sur \( [0,1] \), \( I_n \) est strictement positif pour tout naturel \( n \). On en déduit que \( \forall n\in\Nn,\;\frac{I_{n+1}}{I_n}\le\frac{I_{n+2}}{I_{n+1}} \) et donc que

\begin{center}
\shadowbox{ la suite \( \left(\frac{I_{n+1}}{I_n}\right)_{n\in\Nn} \) est définie et croissante. }
\end{center}

exercices.enonce:
Soit \( f \) une application de \( \Cc \) dans \( \Cc \), \( \Rr \)-linéaire.

	\begin{enumerate}
		\item Montrer qu'il existe deux complexes \( a \) et \( b \) tels que pour tout \( z\in\Cc \), \( f(z) = az + b\overline{z} \).

		\item Calculer \( \text{Tr}(f) \) et \( \text{det}(f) \) en fonction de \( a \) et \( b \).

		\item C.N.S. pour que \( f \) soit autoadjoint dans \( \Cc \) muni de sa structure euclidienne canonique.
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Soit \( f \) un endomorphisme du \( \Rr \)-espace vectoriel \( \Cc \). Pour tout nombre complexe \( z \)

\begin{align*}\ensuremath f(z) & = f((\text{Re}(z)).1 +(\text{Im}(z)).i) =(\text{Re}(z))f(1) +(\text{Im}(z))f(i) =\frac{1}{2}(z+\overline{z})f(1)+\frac{1}{2i}(z-\overline{z})f(i) \\
	& = \frac{f(1)-if(i)}{2}z +\frac{f(1)+if(i)}{2}\overline{z},
\end{align*}

et on peut prendre \( a = \frac{f(1)-if(i)}{2} \) et \( b = \frac{f(1)+if(i)}{2} \). (Réciproquement pour \( a \) et \( b \) complexes donnés, l'application \( f \) ainsi définie est \( \Rr \)-linéaire et on a donc l'écriture générale complexe d'un endomorphisme du plan).

\item

\begin{center}
	\( \text{Tr}(f) = \text{Re}(f(1)) +\text{Im}(f(i)) = \text{Re}(a+b)+\text{Im}(i(a-b)) = \text{Re}(a+b)+\text{Re}(a-b) = 2\text{Re}(a) \)
\end{center}

et

\begin{align*}\ensuremath
	\text{det}(f) & =\text{Re}(a+b)\text{Im}(i(a-b))-\text{Im}(a+b)\text{Re}(i(a-b))=\text{Re}(a+b)\text{Re}(a-b)+\text{Im}(a+b)\text{Im}(a-b) \\
	& =(\text{Re}(a))^2 -(\text{Re}(b))^2+(\text{Im}(a))^2-(\text{Im}(b))^2=|a|^2 - |b|^2.
\end{align*}

\begin{center}
	\shadowbox{ \( \text{Tr}(f) = 2\text{Re}(a) \) et \( \text{det}(f) = |a|^2 - |b|^2 \). }
\end{center}

\item Soient \( z \) et \( z' \) deux nombres complexes. On rappelle que

\begin{center}
	\( z|z' = (\text{Re}z)(\text{Re}z')+(\text{Im}z)(\text{Im}z') = \frac{1}{4}(z+\overline{z})(z'+\overline{z'})-\frac{1}{4}(z-\overline{z})(z'-\overline{z'}) = \frac{1}{2}(\overline{z}z'+z\overline{z'}) = \text{Re}(\overline{z}z') \).
\end{center}

et au passage si on oriente le plan de sorte que la base orthonormée \( (1,i) \) soit directe,

\begin{center}
	\( [z,z'] = (\text{Re}z)(\text{Im}z')+(\text{Im}z)(\text{Re}z') = \frac{1}{4i}(z+\overline{z})(z'-\overline{z'})-\frac{1}{4i}(z-\overline{z})(z'+\overline{z'}) = \frac{1}{2i}(\overline{z}z'-z\overline{z'}) = \text{Im}(\overline{z}z') \).
\end{center}

Notons \( M \) la matrice de \( f \) dans la base \( (1,i) \). Puisque la base \( (1,i) \) est orthonormée,

\begin{center}
	\( f = f^*\Leftrightarrow M = {^t}M\Leftrightarrow\text{Im}(a+b) = \text{Re}(i(a-b))\Leftrightarrow\text{Im}(a+b) = -\text{Im}(a-b)\Leftrightarrow2\text{Im}a = 0\Leftrightarrow a\in\Rr \).
\end{center}

\begin{center}
	\shadowbox{ \( f = f^*\Leftrightarrow a\in\Rr \). }
\end{center}
\end{enumerate}

exercices.enonce:
Soit \( E \) un espace vectoriel sur un corps \( K \) (\( K = \Rr \) ou \( \Cc \)), on appelle {\it projecteur}
	un endomorphisme \( p \) de \( E \) vérifiant \( p\circ p = p \). Soit \( p \) un projecteur.
	\begin{enumerate}
		\item Montrer que \( \mathrm{\mathrm{Id}}_E-p \) est un projecteur, calculer \( p\circ(\mathrm{Id}_E-p) \) et \( (\mathrm{Id}_E-p)\circ p \).

		\item Montrer que pour tout \( \vec x\in \Im p \), on a \( p(\vec x) = \vec x \).

		\item En déduire que \( \Im p \) et \( \ker p \) sont supplémentaires.

		\item Montrer que le rang de \( p \) est égal à la trace de \( p \). (On rappelle que la trace de la matrice d'un endomorphisme ne dépend pas de la base dans laquelle on exprime cette matrice.)
	\end{enumerate}

