\item \( ]1,+\infty[ \).

\item

\item \( I'(a) = - \int_{x = 0}^{+\infty}\sh xe^{-ax}\,d x = \frac12\Bigl(\frac1{a-1}-\frac1{a+1}\Bigr) \). D'où \( I(a) = \frac12\ln\Bigl(\frac{a-1}{a+1}\Bigr) + \) cste et \( I(a)\to 0 \) lorsque \( a\to+\infty \) donc la constante est nulle.
\end{enumerate}

exercices.enonce:
Pour \( n\in\Nn^* \) et \( x\in]0,+\infty[ \), on pose \( I_n(x) = \int_0^{+\infty}\frac{1}{(t^2+x^2)^n} \).

	\begin{enumerate}
		\item Calculer la dérivée de la fonction \( I_n \) sur \( ]0,+\infty[ \).

		\item En déduire la valeur de \( \int_0^{+\infty}\frac{1}{(t^2+1)^3}\;dt \).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Soit \( n\in\Nn^* \). Soient \( a \) et \( A \) deux réels tels que \( 0<a<A \). On considère \( \begin{array}[t]{cccc}
	F_n : & [a,A]\times\Rr & \rightarrow & \Rr                   \\
	& (x,t)          & \mapsto     & \frac{1}{(t^2+x^2)^n}
\end{array} \).

\textbullet Pour chaque \( x \) de \( [a,A] \), la fonction \( t\mapsto F_n(x,t) \) est continue par morceaux et intégrable sur \( [0,+\infty[ \) car \( F_n(x,t)\underset{t\rightarrow+\infty}{\sim}\frac{1}{t^{2n}}>0 \) avec \( 2n>1 \).

\textbullet La fonction \( F_n \) est admet sur \( [a,A]\times[0,+\infty[ \) une dérivée partielle par rapport à sa première variable \( x \) définie par :

\begin{center}
	\( \forall(x,t)\in[a,A]\times[0,+\infty[ \), \( \frac{\partial F_n}{\partial x}(x,t) = \frac{-2nx}{(t^2+x^2)^{n+1}} \).
\end{center}

De plus,

- pour chaque \( x\in[a,A] \), la fonction \( t\mapsto\frac{\partial F_n}{\partial x}(x,t) \) est continue par morceaux sur \( [0,+\infty[ \),\rule[-4mm]{0mm}{0mm}

-pour chaque \( t\in[0,+\infty[ \), la fonction \( x\mapsto\frac{\partial F_n}{\partial x}(x,t) \) est continue sur \( [a,A] \),

-pour chaque \( (x,t)\in[a,A]\times[0,+\infty[ \),

\begin{center}
	\( \left|\frac{\partial F_n}{\partial x}(x,t)\right| = \frac{2nx}{(t^2+x^2)^{n+1}}\le\frac{2nA}{(t^2+a^2)^{n+1}} = \varphi(t) \),
\end{center}

où la fonction \( \varphi \) est continue par morceaux et intégrable sur \( [0,+\infty[ \) car négligeable devant \( \frac{1}{t^2} \) quand \( t \) tend vers \( +\infty \).

D'après le théorème de dérivation des intégrales à paramètres (théorème de \textsc{Leibniz}), la fonction \( I_n \) est de classe \( C^1 \) sur \( [a,A] \) et sa dérivée s'obtient par dérivation sous le signe somme. Ceci étant vrai pour tous réels \( a \) et \( A \) tels que \( 0<a<A \), on a montré que la fonction \( I_n \) est de classe \( C^1 \) sur \( ]0,+\infty[ \) et que

\begin{center}
	\( \forall x>0 \), \( I_n'(x) = -2nx\int_0^{+\infty}\frac{1}{(t^2+x^2)^{n+1}}\;dt = -2nxI_{n+1}(x) \).
\end{center}

\begin{center}
	\shadowbox{ \( \forall n\in\Nn^* \), \( I_n'(x) = -2nxI_{n+1}(x) \). }
\end{center}

\item Pour \( x>0 \), on a \( I_1(x) = \left[\frac{1}{x}\arctan\left(\frac{t}{x}\right)\right]_0^{+\infty} = \frac{\pi}{2x} \). Ensuite, \( I_2(x) = -\frac{1}{2x}I_1'(x) = \frac{\pi}{4x^3} \) puis \( I_3(x) = -\frac{1}{4x}I_2'(x) = \frac{3\pi}{16x^5} \) et donc \( I_3(1) = \frac{3\pi}{16} \).

\begin{center}
	\shadowbox{ \( \int_0^{+\infty}\frac{1}{(t^2+1)^3}\;dt = \frac{3\pi}{16} \). }
\end{center}
\end{enumerate}

Soit \( x\in\Rr \). La fonction \( t\mapsto e^{-t^2}\ch(tx) \) est continue sur \( [0,+\infty[ \). Quand \( t \) tend vers \( +\infty \), \( e^{-t^2}\ch(tx) = \frac{1}{2}(e^{-t^2+tx}+e^{-t^2-tx}) = o\left(\frac{1}{t^2}\right) \) d'après un théorème de croissances comparées et donc la fonction \( t\mapsto e^{-t^2}\ch(tx) \) est intégrable sur \( [0,+\infty[ \). Pour \( x\in\Rr \), on peut poser \( f(x) = \int_0^{+\infty}e^{-t^2}\ch(tx)\;dt \).

\textbf{Calcul de \( f(x) \).} Soit \( A>0 \). On pose \( \begin{array}[t]{cccc}
\Phi : & [-A,A]\times[0,+\infty[ & \rightarrow & \Rr             \\
& (x,t)                   & \mapsto     & e^{-t^2}\ch(tx)
\end{array} \).

\textbullet Pour chaque \( x\in[-A,A] \), la fonction \( t\mapsto e^{-t^2}\ch(tx) \) est continue par morceaux et intégrable sur \( [0,+\infty[ \).

\textbullet La fonction \( \Phi \) admet sur \( [-A,A]\times[0,+\infty[ \) une dérivée partielle par rapport à sa première variable définie par :

\begin{center}
\( \forall(x,t)\in[-A,A]\times[0,+\infty[ \), \( \frac{\partial \Phi}{\partial x}(x,t) = te^{-t^2}\sh(tx) \).
\end{center}

De plus,

- pour chaque \( x\in[-A,A] \), la fonction \( t\mapsto\frac{\partial \Phi}{\partial x}(x,t) \) est continue par morceaux sur \( [0,+\infty[ \),

-pour chaque \( t\in[0,+\infty[ \), la fonction \( x\mapsto\frac{\partial \Phi}{\partial x}(x,t) \) est continue sur \( [-A,A] \),

- pour chaque \( (x,t)\in[-A,A]\times[0,+\infty[ \),

\begin{center}
\( \left|\frac{\partial \Phi}{\partial x}(x,t)\right| = te^{-t^2}|\sh(tx)|\le te^{-t^2}\sh(t|A|) = \varphi(t) \).
\end{center}

La fonction \( \varphi \) est continue par morceaux sur \( [0,+\infty[ \) et intégrable sur \( [0,+\infty[ \) car négligeable devant \( \frac{1}{t^2} \) quand \( t \) tend vers \( +\infty \).

D'après le théorème de dérivation des intégrales à paramètres (théorème de \textsc{Leibniz}), la fonction \( f \) est de classe \( C^1 \) sur \( [-A,A] \) et sa dérivée s'obtient par dérivation sous le signe somme. Ceci étant vrai pour tout réel \( A>0 \), la fonction \( f \) est de classe \( C^1 \) sur \( \Rr \) et

\begin{center}
\( \forall x\in\Rr \), \( f'(x) = \int_0^{+\infty}te^{-t^2}\sh(tx)\;dt \).
\end{center}

Soit \( x\in\Rr \). On effectue maintenant une intégration par parties. Soit \( A>0 \). Les deux fonctions \( t\mapsto te^{-t^2} \) et \( t\mapsto\sh(tx) \) sont de classe \( C^1 \) sur le segment \( [0,A] \). On peut donc effectuer une intégration par parties et on obtient

\begin{center}
\( \int_0^Ate^{-t^2}\sh(tx)\;dt = \left[-\frac{1}{2}e^{-t^2}\sh(tx)\right]_0^A+\frac{x}{2}\int_0^Ae^{-t^2}\ch(tx)\;dt = -\frac{1}{2}e^{-A^2}\sh(tA)+\frac{x}{2}\int_0^Ae^{-t^2}\ch(tx)\;dt \).
\end{center}

Quand \( A \) tend vers \( +\infty \), on obtient \( f'(x) = \int_0^{+\infty}te^{-t^2}\sh(tx)\;dt = \frac{x}{2}\int_0^{+\infty}e^{-t^2}\ch(tx)\;dt = \frac{x}{2}f(x) \).

Ensuite, pour tout réel \( x \), \( e^{-x^2/4}f'(x)-\frac{x}{2}e^{-x^2/4}f(x) = 0 \) ou encore \( (e^{-x^2/4}f)'(x) = 0 \). On en déduit que \( \forall x\in\Rr \), \( e^{-x^2/4}f(x) = e^0f(0) = \int_0^{+\infty}e^{-t^2}\;dt = \frac{\sqrt{\pi}}{2} \) et donc que \( \forall x\in\Rr \), \( f(x) = \frac{\sqrt{\pi}}{2}e^{x^2/4} \).

\begin{center}
\shadowbox{ \( \forall x\in\Rr \), \( \int_0^{+\infty}e^{-t^2}\ch(tx)\;dt = \frac{\sqrt{\pi}}{2}e^{x^2/4} \). }
\end{center}

Soit \( x\in\Rr \). La fonction \( t\mapsto \frac{t-1}{\ln t}t^x \) est continue sur \( ]0,1[ \).

\textbf{Etude en \( 1 \).} \( \frac{t-1}{\ln t}t^x\underset{t\rightarrow1}{\sim}1\times1 = 1 \) et donc la fonction \( t\mapsto \frac{t-1}{\ln t}t^x \) se prolonge par continuité en \( 1 \). On en déduit que la fonction \( t\mapsto \frac{t-1}{\ln t}t^x \) est intégrable sur un voisinage de \( 1 \) à gauche.

\textbf{Etude en \( 0 \).} \( \frac{t-1}{\ln t}t^x\underset{t\rightarrow0}{\sim}-\frac{t^x}{\ln t}>0 \).

-si \( x>-1 \), \( -\frac{t^x}{\ln t}\underset{t\rightarrow0}{ = }o(t^x) \) et puisque \( x>-1 \), la fonction \( t\mapsto \frac{t-1}{\ln t}t^x \) est intégrable sur un voisinage de \( 0 \) à droite.

- si \( x\le-1 \), la fonction \( t\mapsto-\frac{t^x}{\ln t} \) domine la fonction \( t\mapsto-\frac{1}{t\ln t} \) quand \( t \) tend vers \( 0 \) par valeurs supérieures. Puisque la fonction \( -\frac{1}{t\ln t} \) est positive et que \( \int_x^{1/2}-\frac{1}{t\ln t}\;dt = \ln|\ln(x)|-\ln|\ln(1/2)|\underset{x\rightarrow0}{\rightarrow}+\infty \), la fonction \( t\mapsto-\frac{1}{t\ln t} \) n'est pas intégrable sur un voisinage de \( 0 \). Il en est de même de la fonction \( t\mapsto\frac{t-1}{\ln t}t^x \).

Finalement, la fonction \( t\mapsto\frac{t-1}{\ln t}t^x \) est intégrable sur \( ]0,1[ \) si et seulement si \( x>-1 \). Pour \( x>-1 \), on peut poser \( f(x) = \int_0^1\frac{t-1}{\ln t}t^x\;dt \).

\textbf{Calcul de \( f(x) \).} Soit \( a>-1 \). On pose \( \begin{array}[t]{cccc}
\Phi : & [a,+\infty[\times]0,1[ & \rightarrow & \Rr                  \\
& (x,t)                  & \mapsto     & \frac{t-1}{\ln t}t^x
\end{array} \).

\textbullet Pour chaque \( x\in[a,+\infty[ \), la fonction \( t\mapsto \frac{t-1}{\ln t}t^x \) est continue par morceaux et intégrable sur \( ]0,1[ \).

\textbullet La fonction \( \Phi \) admet sur \( [a,+\infty[\times]0,1[ \) une dérivée partielle par rapport à sa première variable définie par :

\begin{center}
\( \forall(x,t)\in[a,+\infty[\times]0,1[ \), \( \frac{\partial \Phi}{\partial x}(x,t) = (t-1)t^x = t^{x+1}-t^x \).
\end{center}

De plus,

- pour chaque \( x\in[a,+\infty[ \), la fonction \( t\mapsto\frac{\partial \Phi}{\partial x}(x,t) \) est continue par morceaux sur \( ]0,1[ \),

-pour chaque \( t\in]0,1[ \), la fonction \( x\mapsto\frac{\partial \Phi}{\partial x}(x,t) \) est continue sur \( [a,+\infty[ \),

- pour chaque \( (x,t)\in[a,+\infty[\times]0,1[ \),

\begin{center}
\( \left|\frac{\partial \Phi}{\partial x}(x,t)\right| = (1-t)t^a = \varphi(t) \).
\end{center}

La fonction \( \varphi \) est continue par morceaux sur \( ]0,1[ \) et intégrable sur \( ]0,1[ \) car \( a>-1 \).

D'après le théorème de dérivation des intégrales à paramètres (théorème de \textsc{Leibniz}), la fonction \( f \) est de classe \( C^1 \) sur \( [a,+\infty[ \) et sa dérivée s'obtient par dérivation sous le signe somme. Ceci étant vrai pour tout réel \( a>-1 \), la fonction \( f \) est de classe \( C^1 \) sur \( ]-1,+\infty[ \) et

\begin{center}
\( \forall x>-1 \), \( f'(x) = \int_0^1(t-1)t^x\;dt = \left[\frac{t^{x+2}}{x+2}-\frac{t^{x+1}}{x+1}\right]_0^1 = \frac{1}{x+2}-\frac{1}{x+1} \).
\end{center}

Par suite, il existe \( C\in\Rr \) tel que \( \forall x>-1 \), \( f(x) = \ln\left(\frac{x+2}{x+1}\right)+C \)\quad\( (*) \). Pour déterminer la constante \( C \), on peut utiliser le résultat de l'exercice \ref{ex:rou7bis} : \( \int_0^1\frac{t-1}{\ln t}\;dt = \ln2 \). On peut aussi obtenir directement la constante \( C \) sans aucun calcul d'intégrale. Pour cela, déterminons \( \lim_{x \rightarrow +\infty}f(x) \).

La fonction \( g : t\mapsto\frac{t-1}{\ln t} \) est continue sur le segment \( ]0,1[ \), prolongeable par continuité en \( 0 \) et en \( 1 \) en posant \( g(0) = 0 \) et \( g(1) = 1 \). On en déduit que cette fonction est bornée sur l'intervalle \( ]0,1[ \) (car son prolongement est une fonction continue sur un segment).

Soit \( M \) un majorant de la fonction \( |g| \) sur \( ]0,1[ \). Pour \( x>-1 \), on a

\begin{center}
\( |g(x)|\le M\int_0^1t^x\;dt = \frac{M}{x+1} \).
\end{center}

Ceci montre que \( \lim_{x \rightarrow +\infty}f(x) = 0 \) et en passant à la limite quand \( x \) tend vers \( +\infty \) dans l'égalité \( (*) \), on obtient \( C = 0 \). On a donc montré que

\begin{center}
\shadowbox{ \( \forall x>-1 \), \( \int_0^1\frac{t-1}{\ln t}t^x\;dt = \ln\left(\frac{x+2}{x+1}\right) \). }
\end{center}

On retrouve en particulier \( \int_0^1\frac{t-1}{\ln t}\;dt = \ln2 \).

\textbf{Existence de \( \int_0^{+\infty}\frac{e^{-tx}}{1+t^2}\;dt \).} Soit \( x\ge0 \). La fonction \( t\mapsto\frac{e^{-tx}}{1+t^2} \) est continue sur \( [0,+\infty[ \) et est dominée par \( \frac{1}{t^2} \) quand \( t \) tend vers \( +\infty \). Cette fonction est donc intégrable sur \( [0,+\infty[ \). Donc \( \int_0^{+\infty}\frac{e^{-tx}}{1+t^2}\;dt \) existe pour tout réel positif \( x \) et on pose \( \forall x\ge 0 \), \( f(x) = \int_0^{+\infty}\frac{e^{-tx}}{1+t^2}\;dt \).

\textbf{Continuité de \( f \) sur \( [0,+\infty[ \).} Soit \( \begin{array}[t]{cccc}
\Phi : & [0,+\infty[\times[0,+\infty[ & \rightarrow & \Rr                   \\
& (x,t)                        & \mapsto     & \frac{e^{-tx}}{1+t^2}
\end{array} \).

\textbullet Pour chaque \( x\in[0,+\infty[ \), la fonction \( t\mapsto\Phi(x,t) \) est continue par morceaux sur \( [0,+\infty[ \).

\textbullet Pour chaque \( t\in[0,+\infty[ \), la fonction \( x\mapsto\Phi(x,t) \) est continue sur \( [0,+\infty[ \).

\textbullet Pour chaque \( (x,t)\in[0,+\infty[\times[0,+\infty[ \),

\begin{center}
\( |\Phi(x,t)| = \frac{e^{-tx}}{1+t^2}\;dt\le\frac{1}{1+t^2} = \varphi_0(t) \).
\end{center}

De plus, la fonction \( \varphi_0 \) est continue et intégrable sur \( [0,+\infty[ \) car équivalente à \( \frac{1}{t^2} \) quand \( t \) tend vers \( +\infty \).

D'après le théorème de continuité des intégrales à paramètres, \( f \) est continue sur \( [0,+\infty[ \).

\textbf{Dérivée seconde de \( f \).} Soit \( a>0 \). On pose \( \begin{array}[t]{cccc}
\Phi : & [0,+\infty[\times[a,+\infty[ & \rightarrow & \Rr                   \\
& (x,t)                        & \mapsto     & \frac{e^{-tx}}{1+t^2}
\end{array} \).

En plus de ce qui précède, \( \Phi \) admet sur \( [a,+\infty[\times[0,+\infty[ \) des dérivées partielles d'ordre \( 1 \) et \( 2 \) définies par

\begin{center}
\( \forall(x,t)\in[a,+\infty[\times[0,+\infty[ \), \( \frac{\partial\Phi}{\partial x}(x,t) = -\frac{te^{-tx}}{1+t^2} \) et \( \frac{\partial^2\Phi}{\partial x^2}(x,t) = \frac{t^2e^{-tx}}{1+t^2} \).
\end{center}

\textbullet Pour chaque \( x\in[a,+\infty[ \), les fonctions \( t\mapsto\frac{\partial\Phi}{\partial x}(x,t) \) et \( t\mapsto\frac{\partial^2\Phi}{\partial x^2}(x,t) \) sont continues par morceaux sur \( [0,+\infty[ \).

\textbullet Pour chaque \( t\in[0,+\infty[ \), les fonctions \( x\mapsto\frac{\partial\Phi}{\partial x}(x,t) \) et \( x\mapsto\frac{\partial^2\Phi}{\partial x^2}(x,t) \) sont continues sur \( [a,+\infty[ \).

\textbullet Pour chaque \( (x,t)\in[a,+\infty[\times[0,+\infty[ \),

\begin{center}
\( \left|\frac{\partial\Phi}{\partial x}(x,t)\right| = \frac{te^{-tx}}{1+t^2}\le\frac{te^{-at}}{1+t^2} = \varphi_1(t) \) et \( \left|\frac{\partial^2\Phi}{\partial x}(x,t)\right| = \frac{t^2e^{-tx}}{1+t^2}\le\frac{t^2e^{-at}}{1+t^2} = \varphi_2(t) \).
\end{center}

De plus, les fonctions \( \varphi_1 \) et \( \varphi_2 \) sont continues par morceaux et intégrables sur \( [0,+\infty[ \) car négligeables devant \( \frac{1}{t^2} \) quand \( t \) tend vers \( +\infty \).

D'après une généralisation du théorème de dérivation des intégrales à paramètres, \( f \) est de classe \( C^2 \) sur \( [a,+\infty[ \) et ses dérivées premières et secondes s'obtiennent par dérivation sous le signe somme. Ceci étant vrai pour tout \( a>0 \), \( f \) est de classe \( C^2 \) sur \( ]0,+\infty[ \) et

\begin{center}
\shadowbox{ \( \forall x>0 \), \( f'(x) = \int_0^{+\infty}\frac{te^{-tx}}{1+t^2}\;dt \) et \( f''(x) = \int_0^{+\infty}\frac{t^2e^{-tx}}{1+t^2}\;dt \). }
\end{center}

\textbf{Equation différentielle vérifiée par \( f \).} Pour \( x>0 \),

\begin{center}
\( f''(x)+f(x) = \int_0^{+\infty}\frac{t^2e^{-tx}}{1+t^2}\;dt+\int_0^{+\infty}\frac{e^{-tx}}{1+t^2}\;dt = \int_0^{+\infty}e^{-tx}\;dt = \left[-\frac{e^{-tx}}{x}\right]_0^{+\infty} = \frac{1}{x} \).
\end{center}

\begin{center}
\shadowbox{ \( \forall x>0 \), \( f(x)+f''(x) = \frac{1}{x} \). }
\end{center}

\textbf{Existence de \( \int_0^{+\infty}\frac{\sin t}{x+t}\;dt \).} Si \( x = 0 \), l'exercice \ref{ex:rou3}, 1) montre que \( \int_0^{+\infty}\frac{\sin t}{t}\;dt \) est une intégrale convergente.

Si \( x>0 \), une intégration par parties fournit pour \( A>0 \)

\begin{center}
\( \int_0^A\frac{\sin t}{t+x}\;dt = -\frac{\cos A}{A+x}+\frac{1}{x}-\int_0^A\frac{\cos t}{(t+x)^2}\;dt \).
\end{center}

La fonction \( t\mapsto\frac{\cos t}{(t+x)^2} \) est continue sur \( [0,+\infty[ \) et est dominée par \( \frac{1}{t^2} \) quand \( t \) tend vers \( +\infty \). Cette fonction est donc intégrable sur \( [0,+\infty[ \). On en déduit que la fonction \( A\mapsto\int_0^A\frac{\cos t}{(t+x)^2}\;dt \) a une limite réelle quand \( A \) tend vers \( +\infty \) et il en est de même de la fonction \( A\mapsto\int_0^A\frac{\sin t}{t+x}\;dt \). Ainsi, pour chaque \( x\in[0,+\infty[ \), \( \int_0^{+\infty}\frac{\sin t}{t+x}\;dt \) est une intégrale convergente. Pour \( x\ge 0 \), on peut donc poser \( g(x) = \int_0^{+\infty}\frac{\sin t}{t+x}\;dt \).

\textbf{Equation différentielle vérifiée par \( g \).} Pour \( x>0 \), on pose \( u = x+t \). on obtient

\begin{center}
\( g(x) = \int_0^{+\infty}\frac{\sin t}{t+x}\;dt = \int_x^{+\infty}\frac{\sin(u-x)}{u}\;du = \cos x\int_x^{+\infty}\frac{\sin u}{u}\;du-\sin x\int_x^{+\infty}\frac{\cos u}{u}\;du \).
\end{center}

(car toutes les intégrales considérées sont convergentes). Maintenant, les fonctions \( c : u\mapsto\frac{\cos u}{u} \) et \( s : u\mapsto\frac{\sin u}{u} \) sont continues sur \( ]0,+\infty[ \) et admettent donc des primitives sur \( ]0,+\infty[ \). On note \( C \) (respectivement \( S \)) une primitive de la fonction \( c \) (respectivement \( s \)) sur \( ]0,+\infty[ \)). Pour tout réel \( x>0 \), \( \int_x^{+\infty}\frac{\cos u}{u}\;du = \lim_{t \rightarrow +\infty}C(t)-C(x) \). On en déduit que la fonction \( x\mapsto\int_x^{+\infty}\frac{\cos u}{u}\;du \) est de classe \( C^1 \) sur \( ]0,+\infty[ \), de dérivée \( -c \). De même, la fonction \( x\mapsto\int_x^{+\infty}\frac{\sin u}{u}\;du \) est de classe \( C^1 \) sur \( ]0,+\infty[ \), de dérivée \( -s \). Mais alors la fonction \( g \) est de classe \( C^1 \) sur \( ]0,+\infty[ \) et pour tout réel \( x>0 \),

\begin{align*}\ensuremath g'(x) & =-\sin x\int_x^{+\infty}\frac{\sin u}{u}\;du-\frac{\sin x\cos x}{x}-\cos x\int_x^{+\infty}\frac{\cos u}{u}\;du+\frac{\cos x\sin x}{x} \\
& =-\cos x\int_x^{+\infty}\frac{\cos u}{u}\;du-\sin x\int_x^{+\infty}\frac{\sin u}{u}\;du.
\end{align*}

La fonction \( g' \) est encore de classe \( C^1 \) sur \( ]0,+\infty[ \) et pour tout réel \( x>0 \),

\begin{align*}\ensuremath g'(x) & =\sin x\int_x^{+\infty}\frac{\cos u}{u}\;du+\frac{\cos^2 x}{x}-\cos x\int_x^{+\infty}\frac{\sin u}{u}\;du+\frac{\sin^2 x}{x} \\
& =\frac{1}{x}-g(x).
\end{align*}

\begin{center}
\shadowbox{ \( \forall x>0 \), \( g''(x)+g(x) = \frac{1}{x} \). }
\end{center}

\textbf{Egalité de \( f \) et \( g \) sur \( ]0,+\infty[ \).} Pour tout réel \( x>0 \), \( (f-g)''(x)+(f-g)(x) = 0 \). Donc il existe deux réels \( \lambda \) et \( \mu \) tels que \( \forall x>0 \), \( (f-g)(x) = \lambda\cos x+\mu\sin x = A\cos(x+\varphi) \) pour \( A = \sqrt{\lambda^2+\mu^2} \) et pour un certain \( \varphi \).

Maintenant, pour \( x>0 \), \( |f(x)| = \int_0^{+\infty}\frac{e^{-tx}}{1+t^2}\;dt\le\int_0^{+\infty}e^{-tx}\;dt = \frac{1}{x} \) et on en déduit que \( \lim_{x \rightarrow +\infty}\frac{1}{x} = 0 \).

Ensuite, \( |g(x)\le\left|\int_x^{+\infty}\frac{\sin u}{u}\;du\right|+\left|\int_x^{+\infty}\frac{\cos u}{u}\;du\right| \). Puisque les intégrales \( \int_1^{+\infty}\frac{\sin u}{u}\;du \) et \( \int_1^{+\infty}\frac{\cos u}{u}\;du \) sont des intégrales convergentes, on a \( \lim_{x \rightarrow +\infty}\int_x^{+\infty}\frac{\sin u}{u}\;du = \lim_{x \rightarrow +\infty}\int_x^{+\infty}\frac{\cos u}{u}\;du = 0 \) et donc aussi \( \lim_{x \rightarrow +\infty}g(x) = 0 \).

Finalement, \( \lim_{x \rightarrow +\infty}(f(x)-g(x)) = 0 \) ce qui impose \( A = 0 \) et donc \( \forall x>0 \), \( f(x) = g(x) \).

\begin{center}
\shadowbox{ \( \forall x>0 \), \( \int_0^{+\infty}\frac{e^{-tx}}{1+t^2}\;dt = \int_0^{+\infty}\frac{\sin t}{t+x}\;dt \). }
\end{center}

\textbf{Continuité de \( g \) en \( 0 \) et valeur de \( \int_0^{+\infty}\frac{\sin t}{t}\;dt \).} Pour \( x>0 \),

\begin{align*}\ensuremath g(x) & =\cos x\int_x^{+\infty}\frac{\sin u}{u}\;du-\sin x\int_x^{+\infty}\frac{\cos u}{u}\;du                                                   \\
& =\cos x\int_x^{+\infty}\frac{\sin u}{u}\;du-\sin x\int_1^{+\infty}\frac{\cos u}{u}\;du+\sin x\int_x^1\frac{1-\cos u}{u}\;du-\sin x\ln x.
\end{align*}

Quand \( x \) tend vers \( 0 \), \( \sin x\ln x\sim x\ln x \) et donc \( \lim_{x \rightarrow 0}\sin x\ln x = 0 \). Ensuite, la fonction \( u\mapsto\frac{1-\cos u}{u} \) est intégrable sur \( ]0,1] \) car continue sur \( ]0,1] \) et prolongeable par continuité en \( 0 \). On en déduit que \( \lim_{x \rightarrow 0}\sin x\int_x^1\frac{1-\cos u}{u}\;du = 0\times\int_0^1\frac{1-\cos u}{u}\;du = 0 \). Il reste

\begin{center}
\( \displaystyle\lim_{\substack{x\rightarrow0\\ x>0}}g(x) = \int_0^{+\infty}\frac{\sin t}{t}\;dt = g(0) \).
\end{center}

La fonction \( g \) est donc continue en \( 0 \). Puisque la fonction \( f \) est également continue en \( 0 \), on en déduit que

\begin{center}
\( g(0) = \displaystyle\lim_{\substack{x\rightarrow0\\ x>0}}g(x) = \displaystyle\lim_{\substack{x\rightarrow0\\ x>0}}f(x) = f(0) = \int_0^{+\infty}\frac{1}{1+t^2}\;dt = \frac{\pi}{2} \).
\end{center}

\begin{center}
\shadowbox{ \( \forall x\ge0 \), \( \int_0^{+\infty}\frac{e^{-tx}}{1+t^2}\;dt = \int_0^{+\infty}\frac{\sin t}{t+x}\;dt \) et en particulier, \( \int_0^{+\infty}\frac{\sin t}{t}\;dt = \frac{\pi}{2} \). }
\end{center}

exercices.enonce:
\begin{enumerate}
		\item Soient \( f \) et \( g \) deux fonctions définies sur \( \Rr \), continues et \( T \)-périodiques (\( T \) réel strictement positif). Pour \( x\in\Rr \), on pose

		\begin{center}
			\( f*g(x) = \int_0^Tf(x-t)g(t)\;dt \).
		\end{center}

		Montrer que la fonction \( f*g \) est définie sur \( \Rr \), continue et \( T \)-périodique.

		\item \( * \) est donc une loi interne sur \( E \), l'espace vectoriel des fonctions définies et continues sur \( \Rr \) et \( T \)-périodiques. Montrer que cette loi est commutative.

	\end{enumerate}

\begin{enumerate}
		\item À l'aide d'une intégration par parties, montrer que \( \int_{t = 0}^{+\infty} \frac{\sin t}t \,d t = \int_{t = 0}^{+\infty} \frac{\sin^2 t}{t^2} \,d t \).

		\item Montrer que \( I_n = \int_{t = 0}^{\pi/2} \frac{\sin^2 nt}{t^2}\,d t \) est comprise entre \( A_n = \int_{t = 0}^{\pi/2} \frac{\sin^2 nt}{\sin^2 t}\,d t \) et \( B_n = \int_{t = 0}^{\pi/2} \cotan^2 t\sin^2 nt\,d t \).

		\item Calculer \( A_n+A_{n+2} - 2A_{n+1} \) et \( A_n-B_n \). En déduire les valeurs de \( A_n \) et \( B_n \) en fonction de \( n \).

