d'où \eqref{ex3}.

\begin{enumerate}
\item \( g(f(x,y)) = xy^2 \sin^2 (xy) \cos x \exp(y^2) \)

\item \begin{align*}
	\frac{\partial (g \circ f)}{\partial x}
	& = y^2 \sin(xy) \exp(y^2) ( 2xy \cos x \cos(xy) - x \sin x\sin(xy) +
	\cos x \sin(xy) )
	\\
	\frac{\partial (g\circ f)}{\partial y}
	& = 2xy \cos x \sin(xy)\exp(y^2) (xy \cos(xy) +(1+y^2) \sin(xy) )
\end{align*}

\item Calculons d'abord
\begin{align*}
	\frac{\partial w}{\partial x}
	& =y\sin(xy)\exp(y^2) +xy^2\cos(xy)\exp(y^2)
	\\
	& =y\exp(y^2)(\sin(xy) +xy\cos(xy))
	\\
	\frac{\partial w}{\partial y}
	& =x\sin(xy)\exp(y^2) +x^2y\cos(xy)\exp(y^2) +2xy^2\sin(xy)\exp(y^2)
	\\
	& = x\exp(y^2)(\sin(xy) +xy\cos(xy) +2y^2\sin(xy))
	\\
	& = x\exp(y^2)((1+2y^2)\sin(xy) +xy\cos(xy)) .
\end{align*}
Ainsi la matrice jacobienne \( \mathrm J_f \) de \( f \) s'écrit
\begin{align*}
	\mathrm{J_f} & =
	\left[
	\begin{matrix}
		\frac{\partial u}{\partial x}
		&
		\frac{\partial u}{\partial y}
		\\
		\frac{\partial v}{\partial x}
		&
		\frac{\partial v}{\partial y}
		\\
		\frac{\partial w}{\partial x}
		&
		\frac{\partial w}{\partial y}
	\end{matrix}
	\right]
	\\
	& =
	\left[
	\begin{matrix}
		y \cos(xy)                       & x \cos(xy)
		\\
		-y\sin x                         &
		\cos x
		\\
		y\exp(y^2)(\sin(xy) +xy\cos(xy)) & x\exp(y^2)((1+2y^2)\sin(xy) +xy\cos(xy))
	\end{matrix}
	\right] .
\end{align*}
De même, la matrice jacobienne \( \mathrm J_g \) de \( g \) est :
\begin{align*}
	\mathrm J_g & =
	\left[
	\frac{\partial g}{\partial u}, \frac{\partial g}{\partial v},\frac{\partial g}{\partial w}
	\right]=[vw,uw,uv]
	\\
	& =\left [ xy^2 \sin(xy) \cos x \exp(y^2),xy \sin^2 (xy) \exp(y^2),y \sin(xy) \cos x
	\right]
\end{align*}

\item La matrice jacobienne \( \mathrm J_{g\circ f} \) de la fonction composée \( g\circ f \) s'écrit comme produit matricielle
\begin{align*}
	\mathrm J_{g\circ f} & =\mathrm J_g \circ \mathrm J_f =\left[
	\frac{\partial g}{\partial u}, \frac{\partial g}{\partial v},\frac{\partial g}{\partial w}
	\right]
	\left[
	\begin{matrix}
		\frac{\partial u}{\partial x}
		&
		\frac{\partial u}{\partial y}
		\\
		\frac{\partial v}{\partial x}
		&
		\frac{\partial v}{\partial y}
		\\
		\frac{\partial w}{\partial x}
		&
		\frac{\partial w}{\partial y}
	\end{matrix}
	\right]
\end{align*}
d'où
\begin{align*}
	\frac{\partial (g \circ f)}{\partial x}
	& = (xy^2 \sin(xy) \cos x \exp(y^2)) y \cos(xy)
	\\
	& \quad -(xy \sin^2 (xy) \exp(y^2)) y\sin x
	\\
	& \quad +(y \sin(xy) \cos x) y\exp(y^2)(\sin(xy) +xy\cos(xy))
	\\
	& = xy^3 \cos x \sin(xy) \cos(xy) \exp(y^2)) - xy^2 \sin x\sin^2 (xy) \exp(y^2)
	\\
	& \quad +y^2 \cos x \sin^2 (xy) \exp(y^2) +xy^3 \cos x \sin(xy) \cos(xy)\exp(y^2)
	\\&= y^2 \sin(xy) \exp(y^2) ( 2xy \cos x \cos(xy) - x \sin x\sin(xy) +
	\cos x \sin(xy) )
	\\
	\frac{\partial (g\circ f)}{\partial y}
	& = (xy^2 \sin(xy) \cos x \exp(y^2)) x\cos(xy)
	\\
	& \quad + (xy \sin^2 (xy) \exp(y^2))
	\cos x
	\\
	& \quad +(y \sin(xy) \cos x) x\exp(y^2)((1+2y^2)\sin(xy) +xy\cos(xy))
	\\
	& = x^2y^2 \cos x\sin(xy)
	\cos(xy)\exp(y^2) +xy \cos x\sin^2 (xy) \exp(y^2)
	\\
	& \quad +xy(1+2y^2) \cos x \sin^2 (xy)
	\exp(y^2) +x^2y^2 \cos x\sin(xy)\cos(xy)\exp(y^2)
	\\
	& = 2 x^2y^2 \cos x\sin(xy)
	\cos(xy)\exp(y^2) +2xy(1+y^2) \cos x\sin^2 (xy) \exp(y^2)
	\\
	& = 2xy \cos x \sin(xy)\exp(y^2) (xy \cos(xy) +(1+y^2) \sin(xy) ) .
\end{align*}
\end{enumerate}

exercices.enonce:
Soit \( f(x,y) = \arcsin\left(\frac{1+xy}{\sqrt{(1+x^2)(1+y^2)}}\right) \) et \( g(x,y) = \arctan x - \arctan y \).

	\begin{enumerate}
		\item Vérifier que \( f \) est définie sur \( \Rr^2 \).

		\item Calculer les dérivées partielles premières de \( f \) et de \( g \).

