\end{align*}

exercices.enonce:
Soit \( a\in\Cc\setminus[-1,1] \).

	\begin{enumerate}
		\item
		\begin{enumerate}
			\item Développer en série trigonométrique la fonction \( f : t\mapsto\frac{1}{a-\cos t} \) (utiliser la racine de plus petit module, notée \( b \), de l'équation \( z^2-az+1 = 0 \)).

			\item La série obtenue est-elle la série de \textsc{Fourier} de \( f \) ?
		\end{enumerate}

		\item Déduire de 1) la valeur des intégrales \( I_n = \int_0^{\pi}\frac{\cos(nt)}{a-\cos t}\;dt \), \( n\in\Nn \).
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item
\begin{enumerate}
	\item Soit \( a\in\Cc\setminus[-1,1] \). Pour tout réel \( t \), \( a-\cos t\neq0 \) et

	\begin{center}
		\( \frac{1}{a-\cos t} = \frac{2}{2a-e^{it}-e^{-it}} = \frac{-2e^{it}}{(e^{it})^2-2ae^{it}+1} \).
	\end{center}

	L'équation \( z^2-2az+1 = 0 \) admet deux solutions non nulles inverses l'une de l'autre. On note \( b \) la solution de plus petit module de sorte que \( |b|\le1 \).

	On ne peut avoir \( |b| = 1 \) car alors il existe \( \theta\in\Rr \) tel que \( b = e^{i\theta} \). On en déduit que \( 2a = b+\frac{1}{b} = 2\cos\theta\in[-2,2] \) puis que \( a\in[-1,1] \) ce qui n'est pas. Donc \( |b|\neq1 \). Plus précisément, puisque \( |b|\le\left|\frac{1}{b}\right| \), on a \( |b|<1 \) et \( \left|\frac{1}{b}\right| \). En particulier, \( b\neq\frac{1}{b} \).

	Ensuite, pour \( |t|<|b| \), on a

	\begin{align*}\ensuremath
		\frac{1}{a-\cos t} & =\frac{-2e^{it}}{(e^{it}-b)\left(e^{it}-\frac{1}{b}\right)}=\frac{2}{\frac{1}{b}-b}\left(\frac{b}{e^{it}-b}-\frac{1/b}{e^{it}-\frac{1}{b}}\right)=\frac{2b}{1-b^2}\left(\frac{be^{-it}}{1-be^{-it}}+\frac{1}{1-be^{it}}\right) \\
		& =\frac{2b}{1-b^2}\left(be^{-it}\sum_{n=0}^{+\infty}b^ne^{-int}+\sum_{n=0}^{+\infty}b^ne^{int}\right)\;(\text{car}\;|be^{it}|=|be^{-it}|=|b|<1)                                                                                 \\
		& =\frac{2b}{1-b^2}\left(\sum_{n=0}^{+\infty}b^{n+1}e^{-i(n+1)t}+\sum_{n=0}^{+\infty}b^ne^{int}\right)=\frac{2b}{1-b^2}\left(1+\sum_{n=1}^{+\infty}b^ne^{int}+\sum_{n=1}^{+\infty}b^ne^{-int}\right)                             \\
		& =\frac{2b}{1-b^2}\left(1+2\sum_{n=1}^{+\infty}b^n\cos(nt)\right).
	\end{align*}

	\begin{center}
		\shadowbox{ \( \forall t\in\Rr \), \( \frac{1}{a-\cos t} = \frac{2b}{1-b^2}\left(1+2\sum_{n = 1}^{+\infty}b^n\cos(nt)\right) \). }
	\end{center}

	\item Pour tout réel \( t\in[-\pi,\pi] \) et tout entier naturel non nul \( n \), on a \( |b^n\cos(nt)|\le|b|^n \). Comme la série numérique de terme général \( |b|^n \) converge, on en déduit que la série de fonctions de terme général \( t\mapsto b^n\cos(nt) \), \( n\in\Nn \), converge normalement et donc uniformément sur le segment \( [-\pi,\pi] \).

	On sait alors que la série obtenue est la série de \textsc{Fourier} de \( f \).

\end{enumerate}

\item Puisque la fonction \( f \) est paire, pour tout entier naturel \( n \), \( a_n(f) = \frac{2}{\pi}\int_0^{\pi}\frac{\cos(nt)}{a-\cos t}\;dt \). Donc, pour tout entier naturel \( n \) (y compris pour \( n = 0 \)),

\begin{center}
	\( \int_0^{\pi}\frac{\cos(nt)}{a-\cos t}\;dt = \frac{\pi a_n(f)}{2} = \frac{2b^{n+1}\pi}{1-b^2} \)
\end{center}

Finalement,

\begin{center}
	\shadowbox{ \( \forall n\in\Nn \), \( \int_0^{\pi}\frac{\cos(nt)}{a-\cos t}\;dt = \frac{2b^{n+1}\pi}{1-b^2} \). }
\end{center}
\end{enumerate}

exercices.enonce:
(un développement en série de fonctions de \( \frac{\pi}{\sin(\pi z)} \) et \( \cotan(\pi z) \)).

	Soit \( \alpha\in\Cc\setminus\Zz \). Soit \( f \) l'application de \( \Rr \) dans \( \Cc \), \( 2\pi \)-périodique telle que \( \forall x\in[-\pi,\pi] \), \( f(x) = \cos(\alpha x) \).

	\begin{enumerate}
		\item Développer la fonction \( f \) en série de \textsc{Fourier}.

		\item En déduire que pour tout \( z\in\Cc\setminus\Zz \),

		\begin{center}
			\( \frac{\pi}{\sin(\pi z)} = \frac{1}{z}+\sum_{n = 1}^{+\infty}(-1)^n\frac{2z}{z^2-n^2} \) et \( \pi\cotan(\pi z) = \frac{1}{z}+\sum_{n = 1}^{+\infty}\frac{2z}{z^2-n^2} \).
		\end{center}
	\end{enumerate}

exercices.correction:
\begin{enumerate}
\item Soit \( \alpha\in\Cc\setminus\Zz \). La fonction \( f \) est \( 2\pi \)-périodique, continue sur \( \Rr \) et de classe \( C^1 \) par morceaux sur \( \Rr \). Donc la série de \textsc{Fourier} de \( f \) converge vers \( f \) sur \( \Rr \) d'après le théorème de \textsc{Dirichlet}.

Puisque \( f \) est paire, \( \forall n\in\Nn^* \), \( b_n(f) = 0 \) puis pour \( n\in\Nn \),

\begin{align*}\ensuremath a_n(f) & =\frac{2}{\pi}\int_0^{\pi}\cos(\alpha x)\cos(nx)\;dx=\frac{1}{\pi}\int_0^{\pi}\left(\cos((n+\alpha)x)+\cos((n-\alpha)x)\right)dx                            \\
	& =\frac{1}{\pi}\left[\frac{\sin((\alpha+n)x)}{\alpha+n}+\frac{\sin((\alpha-n)x)}{\alpha-n}\right]_0^\pi\;(\text{car}\;\alpha\notin\Zz)                       \\
	& =\frac{1}{\pi}\left(\frac{\sin((\alpha+n)\pi)}{\alpha+n}+\frac{\sin((\alpha-n)\pi)}{\alpha-n}\right)=(-1)^n\frac{2\alpha\sin(\alpha\pi)}{\pi(\alpha^2-n^2)}
\end{align*}

Finalement,

\begin{center}
	\shadowbox{ \( \forall\alpha\in\Cc\setminus\Zz \), \( \forall x\in[-\pi,\pi] \), \( \cos(\alpha x) = \frac{\sin(\alpha\pi)}{\alpha\pi}+\frac{\sin(\alpha\pi)}{\pi}\sum_{n = 1}^{+\infty}(-1)^n\frac{2\alpha}{\alpha^2-n^2}\cos(nx) \). }
\end{center}

\item Soit \( z\in\Cc\setminus\Zz \).

On prend \( \alpha = z \) et \( x = 0 \) dans la formule précédente et on obtient \( 1 = \frac{\sin(\pi z)}{\pi z}+\frac{\sin(\pi z)}{\pi}\sum_{n = 1}^{+\infty}(-1)^n\frac{2z}{z^2-n^2} \) \( (*) \). Maintenant,

\begin{center}
	\( \sin(\pi z) = 0\Leftrightarrow\frac{1}{2i}(e^{i\pi z}-e^{-i\pi z}) = 0\Leftrightarrow e^{i\pi z} = e^{-i\pi z}\Leftrightarrow e^{2i\pi z} = 1\Leftrightarrow 2i\pi z\in2i\pi\Zz\Leftrightarrow z\in\Zz \).
\end{center}

Puisque \( z\in\Cc\setminus\Zz \), \( \sin(\pi z)\neq 0 \) et l'égalité \( (*) \) peut s'écrire \( \frac{\pi}{\sin(\pi z)} = \frac{1}{z}+\sum_{n = 1}^{+\infty}(-1)^n\frac{2z}{z^2-n^2} \).

De même, en prenant \( \alpha = z \) et \( x = \pi \), on obtient \( \cos(\pi z) = \frac{\sin(\pi z)}{\pi z}+\frac{\sin(\pi z)}{\pi}\sum_{n = 1}^{+\infty}\frac{2z}{z^2-n^2} \) et donc \( \pi\cotan(\pi z) = \frac{1}{z}+\sum_{n = 1}^{+\infty}\frac{2z}{z^2-n^2} \).

\begin{center}
	\shadowbox{ \( \frac{\pi}{\sin(\pi z)} = \frac{1}{z}+\sum_{n = 1}^{+\infty}(-1)^n\frac{2z}{z^2-n^2} \) et \( \pi\cotan(\pi z) = \frac{1}{z}+\sum_{n = 1}^{+\infty}\frac{2z}{z^2-n^2} \). }
\end{center}
\end{enumerate}

